// Generated by scripts/fetch_verses.py — 和合本 (CUV, public domain) + World English Bible (public domain)
window.BIBLE_TEXT = window.BIBLE_TEXT || {};
window.BIBLE_TEXT["romans"] = {
 "1": {
  "1": {
   "zh": "耶穌基督的僕人保羅，奉召為使徒，特派傳神的福音。",
   "en": "Paul, a servant of Jesus Christ, called to be an apostle, set apart for the Good News of God,"
  },
  "2": {
   "zh": "這福音是神從前藉眾先知在聖經上所應許的，",
   "en": "which he promised before through his prophets in the holy Scriptures,"
  },
  "3": {
   "zh": "論到他兒子─我主耶穌基督。按肉體說，是從大衛後裔生的；",
   "en": "concerning his Son, who was born of the offspring of David according to the flesh,"
  },
  "4": {
   "zh": "按聖善的靈說，因從死裡復活，以大能顯明是神的兒子。",
   "en": "who was declared to be the Son of God with power, according to the Spirit of holiness, by the resurrection from the dead, Jesus Christ our Lord,"
  },
  "5": {
   "zh": "我們從他受了恩惠並使徒的職分，在萬國之中叫人為他的名信服真道；",
   "en": "through whom we received grace and apostleship, for obedience of faith among all the nations, for his name’s sake;"
  },
  "6": {
   "zh": "其中也有你們這蒙召屬耶穌基督的人。",
   "en": "among whom you are also called to belong to Jesus Christ;"
  },
  "7": {
   "zh": "我寫信給你們在羅馬、為神所愛、奉召作聖徒的眾人。願恩惠、平安從我們的父神並主耶穌基督歸與你們！",
   "en": "to all who are in Rome, beloved of God, called to be saints: Grace to you and peace from God our Father and the Lord Jesus Christ."
  },
  "8": {
   "zh": "第一，我靠著耶穌基督，為你們眾人感謝我的神，因你們的信德傳遍了天下。",
   "en": "First, I thank my God through Jesus Christ for all of you, that your faith is proclaimed throughout the whole world."
  },
  "9": {
   "zh": "我在他兒子福音上，用心靈所事奉的神可以見證，我怎樣不住地提到你們；",
   "en": "For God is my witness, whom I serve in my spirit in the Good News of his Son, how unceasingly I make mention of you always in my prayers,"
  },
  "10": {
   "zh": "在禱告之間常常懇求，或者照神的旨意，終能得平坦的道路往你們那裡去。",
   "en": "requesting, if by any means now at last I may be prospered by the will of God to come to you."
  },
  "11": {
   "zh": "因為我切切地想見你們，要把些屬靈的恩賜分給你們，使你們可以堅固；",
   "en": "For I long to see you, that I may impart to you some spiritual gift, to the end that you may be established;"
  },
  "12": {
   "zh": "這樣，我在你們中間，因你與我彼此的信心，就可以同得安慰。",
   "en": "that is, that I with you may be encouraged in you, each of us by the other’s faith, both yours and mine."
  },
  "13": {
   "zh": "弟兄們，我不願意你們不知道，我屢次定意往你們那裡去，要在你們中間得些果子，如同在其餘的外邦人中一樣；只是到如今仍有阻隔。",
   "en": "Now I don’t desire to have you unaware, brothers, that I often planned to come to you, and was hindered so far, that I might have some fruit among you also, even as among the rest of the Gentiles."
  },
  "14": {
   "zh": "無論是希臘人、化外人、聰明人、愚拙人，我都欠他們的債，",
   "en": "I am debtor both to Greeks and to foreigners, both to the wise and to the foolish."
  },
  "15": {
   "zh": "所以情願盡我的力量，將福音也傳給你們在羅馬的人。",
   "en": "So, as much as is in me, I am eager to preach the Good News to you also who are in Rome."
  },
  "16": {
   "zh": "我不以福音為恥；這福音本是神的大能，要救一切相信的，先是猶太人，後是希臘人。",
   "en": "For I am not ashamed of the Good News of Christ, because it is the power of God for salvation for everyone who believes; for the Jew first, and also for the Greek."
  },
  "17": {
   "zh": "因為神的義正在這福音上顯明出來；這義是本於信，以至於信。如經上所記：「義人必因信得生。」",
   "en": "For in it is revealed God’s righteousness from faith to faith. As it is written, “But the righteous shall live by faith.”"
  },
  "18": {
   "zh": "原來，神的忿怒從天上顯明在一切不虔不義的人身上，就是那些行不義阻擋真理的人。",
   "en": "For the wrath of God is revealed from heaven against all ungodliness and unrighteousness of men, who suppress the truth in unrighteousness,"
  },
  "19": {
   "zh": "神的事情，人所能知道的，原顯明在人心裡，因為神已經給他們顯明。",
   "en": "because that which is known of God is revealed in them, for God revealed it to them."
  },
  "20": {
   "zh": "自從造天地以來，神的永能和神性是明明可知的，雖是眼不能見，但藉著所造之物就可以曉得，叫人無可推諉。",
   "en": "For the invisible things of him since the creation of the world are clearly seen, being perceived through the things that are made, even his everlasting power and divinity; that they may be without excuse."
  },
  "21": {
   "zh": "因為，他們雖然知道神，卻不當作神榮耀他，也不感謝他。他們的思念變為虛妄，無知的心就昏暗了。",
   "en": "Because, knowing God, they didn’t glorify him as God, neither gave thanks, but became vain in their reasoning, and their senseless heart was darkened."
  },
  "22": {
   "zh": "自稱為聰明，反成了愚拙，",
   "en": "Professing themselves to be wise, they became fools,"
  },
  "23": {
   "zh": "將不能朽壞之神的榮耀變為偶像，彷彿必朽壞的人和飛禽、走獸、昆蟲的樣式。",
   "en": "and traded the glory of the incorruptible God for the likeness of an image of corruptible man, and of birds, and four-footed animals, and creeping things."
  },
  "24": {
   "zh": "所以，神任憑他們逞著心裡的情慾行污穢的事，以致彼此玷辱自己的身體。",
   "en": "Therefore God also gave them up in the lusts of their hearts to uncleanness, that their bodies should be dishonored among themselves;"
  },
  "25": {
   "zh": "他們將神的真實變為虛謊，去敬拜事奉受造之物，不敬奉那造物的主─主乃是可稱頌的，直到永遠。阿們！",
   "en": "who exchanged the truth of God for a lie, and worshiped and served the creature rather than the Creator, who is blessed forever. Amen."
  },
  "26": {
   "zh": "因此，神任憑他們放縱可羞恥的情慾。他們的女人把順性的用處變為逆性的用處；",
   "en": "For this reason, God gave them up to vile passions. For their women changed the natural function into that which is against nature."
  },
  "27": {
   "zh": "男人也是如此，棄了女人順性的用處，慾火攻心，彼此貪戀，男和男行可羞恥的事，就在自己身上受這妄為當得的報應。",
   "en": "Likewise also the men, leaving the natural function of the woman, burned in their lust toward one another, men doing what is inappropriate with men, and receiving in themselves the due penalty of their error."
  },
  "28": {
   "zh": "他們既然故意不認識神，神就任憑他們存邪僻的心，行那些不合理的事；",
   "en": "Even as they refused to have God in their knowledge, God gave them up to a reprobate mind, to do those things which are not fitting;"
  },
  "29": {
   "zh": "裝滿了各樣不義、邪惡、貪婪、惡毒（或譯：陰毒）；滿心是嫉妒、凶殺、爭競、詭詐、毒恨；",
   "en": "being filled with all unrighteousness, sexual immorality, wickedness, covetousness, malice; full of envy, murder, strife, deceit, evil habits, secret slanderers,"
  },
  "30": {
   "zh": "又是讒毀的、背後說人的、怨恨神的（或譯：被神所憎惡的）、侮慢人的、狂傲的、自誇的、捏造惡事的、違背父母的、",
   "en": "backbiters, hateful to God, insolent, haughty, boastful, inventors of evil things, disobedient to parents,"
  },
  "31": {
   "zh": "無知的、背約的、無親情的、不憐憫人的。",
   "en": "without understanding, covenant breakers, without natural affection, unforgiving, unmerciful;"
  },
  "32": {
   "zh": "他們雖知道神判定行這樣事的人是當死的，然而他們不但自己去行，還喜歡別人去行。",
   "en": "who, knowing the ordinance of God, that those who practice such things are worthy of death, not only do the same, but also approve of those who practice them."
  }
 },
 "2": {
  "1": {
   "zh": "你這論斷人的，無論你是誰，也無可推諉。你在甚麼事上論斷人，就在甚麼事上定自己的罪；因你這論斷人的，自己所行卻和別人一樣。",
   "en": "Therefore you are without excuse, O man, whoever you are who judge. For in that which you judge another, you condemn yourself. For you who judge practice the same things."
  },
  "2": {
   "zh": "我們知道這樣行的人，神必照真理審判他。",
   "en": "We know that the judgment of God is according to truth against those who practice such things."
  },
  "3": {
   "zh": "你這人哪，你論斷行這樣事的人，自己所行的卻和別人一樣，你以為能逃脫神的審判嗎？",
   "en": "Do you think this, O man who judges those who practice such things, and do the same, that you will escape the judgment of God?"
  },
  "4": {
   "zh": "還是你藐視他豐富的恩慈、寬容、忍耐，不曉得他的恩慈是領你悔改呢？",
   "en": "Or do you despise the riches of his goodness, forbearance, and patience, not knowing that the goodness of God leads you to repentance?"
  },
  "5": {
   "zh": "你竟任著你剛硬不悔改的心，為自己積蓄忿怒，以致神震怒，顯他公義審判的日子來到。",
   "en": "But according to your hardness and unrepentant heart you are treasuring up for yourself wrath in the day of wrath, revelation, and of the righteous judgment of God;"
  },
  "6": {
   "zh": "他必照各人的行為報應各人。",
   "en": "who “will pay back to everyone according to their works:”"
  },
  "7": {
   "zh": "凡恆心行善、尋求榮耀、尊貴和不能朽壞之福的，就以永生報應他們；",
   "en": "to those who by perseverance in well-doing seek for glory, honor, and incorruptibility, eternal life;"
  },
  "8": {
   "zh": "惟有結黨、不順從真理、反順從不義的，就以忿怒、惱恨報應他們；",
   "en": "but to those who are self-seeking, and don’t obey the truth, but obey unrighteousness, will be wrath and indignation,"
  },
  "9": {
   "zh": "將患難、困苦加給一切作惡的人，先是猶太人，後是希臘人，",
   "en": "oppression and anguish, on every soul of man who does evil, to the Jew first, and also to the Greek."
  },
  "10": {
   "zh": "卻將榮耀、尊貴、平安加給一切行善的人，先是猶太人，後是希臘人。",
   "en": "But glory, honor, and peace go to every man who does good, to the Jew first, and also to the Greek."
  },
  "11": {
   "zh": "因為神不偏待人。",
   "en": "For there is no partiality with God."
  },
  "12": {
   "zh": "凡沒有律法犯了罪的，也必不按律法滅亡；凡在律法以下犯了罪的，也必按律法受審判。",
   "en": "For as many as have sinned without the law will also perish without the law. As many as have sinned under the law will be judged by the law."
  },
  "13": {
   "zh": "（原來在神面前，不是聽律法的為義，乃是行律法的稱義。",
   "en": "For it isn’t the hearers of the law who are righteous before God, but the doers of the law will be justified"
  },
  "14": {
   "zh": "沒有律法的外邦人若順著本性行律法上的事，他們雖然沒有律法，自己就是自己的律法。",
   "en": "(for when Gentiles who don’t have the law do by nature the things of the law, these, not having the law, are a law to themselves,"
  },
  "15": {
   "zh": "這是顯出律法的功用刻在他們心裡，他們是非之心同作見證，並且他們的思念互相較量，或以為是，或以為非。）",
   "en": "in that they show the work of the law written in their hearts, their conscience testifying with them, and their thoughts among themselves accusing or else excusing them)"
  },
  "16": {
   "zh": "就在神藉耶穌基督審判人隱祕事的日子，照著我的福音所言。",
   "en": "in the day when God will judge the secrets of men, according to my Good News, by Jesus Christ."
  },
  "17": {
   "zh": "你稱為猶太人，又倚靠律法，且指著神誇口；",
   "en": "Indeed you bear the name of a Jew, and rest on the law, and glory in God,"
  },
  "18": {
   "zh": "既從律法中受了教訓，就曉得神的旨意，也能分別是非（或譯：也喜愛那美好的事）；",
   "en": "and know his will, and approve the things that are excellent, being instructed out of the law,"
  },
  "19": {
   "zh": "又深信自己是給瞎子領路的，是黑暗中人的光，",
   "en": "and are confident that you yourself are a guide of the blind, a light to those who are in darkness,"
  },
  "20": {
   "zh": "是蠢笨人的師傅，是小孩子的先生，在律法上有知識和真理的模範。",
   "en": "a corrector of the foolish, a teacher of babies, having in the law the form of knowledge and of the truth."
  },
  "21": {
   "zh": "你既是教導別人，還不教導自己嗎？你講說人不可偷竊，自己還偷竊嗎？",
   "en": "You therefore who teach another, don’t you teach yourself? You who preach that a man shouldn’t steal, do you steal?"
  },
  "22": {
   "zh": "你說人不可姦淫，自己還姦淫嗎？你厭惡偶像，自己還偷竊廟中之物嗎？",
   "en": "You who say a man shouldn’t commit adultery. Do you commit adultery? You who abhor idols, do you rob temples?"
  },
  "23": {
   "zh": "你指著律法誇口，自己倒犯律法、玷辱神嗎？",
   "en": "You who glory in the law, do you dishonor God by disobeying the law?"
  },
  "24": {
   "zh": "神的名在外邦人中，因你們受了褻瀆，正如經上所記的。",
   "en": "For “the name of God is blasphemed among the Gentiles because of you,” just as it is written."
  },
  "25": {
   "zh": "你若是行律法的，割禮固然於你有益；若是犯律法的，你的割禮就算不得割禮。",
   "en": "For circumcision indeed profits, if you are a doer of the law, but if you are a transgressor of the law, your circumcision has become uncircumcision."
  },
  "26": {
   "zh": "所以那未受割禮的，若遵守律法的條例，他雖然未受割禮，豈不算是有割禮嗎？",
   "en": "If therefore the uncircumcised keep the ordinances of the law, won’t his uncircumcision be accounted as circumcision?"
  },
  "27": {
   "zh": "而且那本來未受割禮的，若能全守律法，豈不是要審判你這有儀文和割禮竟犯律法的人嗎？",
   "en": "Won’t the uncircumcision which is by nature, if it fulfills the law, judge you, who with the letter and circumcision are a transgressor of the law?"
  },
  "28": {
   "zh": "因為外面作猶太人的，不是真猶太人；外面肉身的割禮，也不是真割禮。",
   "en": "For he is not a Jew who is one outwardly, neither is that circumcision which is outward in the flesh;"
  },
  "29": {
   "zh": "惟有裡面作的，才是真猶太人；真割禮也是心裡的，在乎靈，不在乎儀文。這人的稱讚不是從人來的，乃是從神來的。",
   "en": "but he is a Jew who is one inwardly, and circumcision is that of the heart, in the spirit not in the letter; whose praise is not from men, but from God."
  }
 },
 "3": {
  "1": {
   "zh": "這樣說來，猶太人有甚麼長處？割禮有甚麼益處呢？",
   "en": "Then what advantage does the Jew have? Or what is the profit of circumcision?"
  },
  "2": {
   "zh": "凡事大有好處：第一是神的聖言交託他們。",
   "en": "Much in every way! Because first of all, they were entrusted with the revelations of God."
  },
  "3": {
   "zh": "即便有不信的，這有何妨呢？難道他們的不信就廢掉神的信嗎？",
   "en": "For what if some were without faith? Will their lack of faith nullify the faithfulness of God?"
  },
  "4": {
   "zh": "斷乎不能！不如說，神是真實的，人都是虛謊的。如經上所記：你責備人的時候，顯為公義；被人議論的時候，可以得勝。",
   "en": "May it never be! Yes, let God be found true, but every man a liar. As it is written, “That you might be justified in your words, and might prevail when you come into judgment.”"
  },
  "5": {
   "zh": "我且照著人的常話說，我們的不義若顯出神的義來，我們可以怎麼說呢？神降怒，是他不義嗎？",
   "en": "But if our unrighteousness commends the righteousness of God, what will we say? Is God unrighteous who inflicts wrath? I speak like men do."
  },
  "6": {
   "zh": "斷乎不是！若是這樣，神怎能審判世界呢？",
   "en": "May it never be! For then how will God judge the world?"
  },
  "7": {
   "zh": "若神的真實，因我的虛謊越發顯出他的榮耀，為甚麼我還受審判，好像罪人呢？",
   "en": "For if the truth of God through my lie abounded to his glory, why am I also still judged as a sinner?"
  },
  "8": {
   "zh": "為甚麼不說，我們可以作惡以成善呢？這是毀謗我們的人說我們有這話。這等人定罪是該當的。",
   "en": "Why not (as we are slanderously reported, and as some affirm that we say), “Let us do evil, that good may come?” Those who say so are justly condemned."
  },
  "9": {
   "zh": "這卻怎麼樣呢？我們比他們強嗎？決不是的！因我們已經證明：猶太人和希臘人都在罪惡之下。",
   "en": "What then? Are we better than they? No, in no way. For we previously warned both Jews and Greeks, that they are all under sin."
  },
  "10": {
   "zh": "就如經上所記：沒有義人，連一個也沒有。",
   "en": "As it is written, “There is no one righteous; no, not one."
  },
  "11": {
   "zh": "沒有明白的；沒有尋求神的；",
   "en": "There is no one who understands. There is no one who seeks after God."
  },
  "12": {
   "zh": "都是偏離正路，一同變為無用。沒有行善的，連一個也沒有。",
   "en": "They have all turned away. They have together become unprofitable. There is no one who does good, no, not so much as one.”"
  },
  "13": {
   "zh": "他們的喉嚨是敞開的墳墓；他們用舌頭弄詭詐，嘴唇裡有虺蛇的毒氣，",
   "en": "“Their throat is an open tomb. With their tongues they have used deceit.” “The poison of vipers is under their lips”;"
  },
  "14": {
   "zh": "滿口是咒罵苦毒。",
   "en": "“whose mouth is full of cursing and bitterness.”"
  },
  "15": {
   "zh": "殺人流血，他們的腳飛跑，",
   "en": "“Their feet are swift to shed blood."
  },
  "16": {
   "zh": "所經過的路便行殘害暴虐的事。",
   "en": "Destruction and misery are in their ways."
  },
  "17": {
   "zh": "平安的路，他們未曾知道；",
   "en": "The way of peace, they haven’t known.”"
  },
  "18": {
   "zh": "他們眼中不怕神。",
   "en": "“There is no fear of God before their eyes.”"
  },
  "19": {
   "zh": "我們曉得律法上的話都是對律法以下之人說的，好塞住各人的口，叫普世的人都伏在神審判之下。",
   "en": "Now we know that whatever things the law says, it speaks to those who are under the law, that every mouth may be closed, and all the world may be brought under the judgment of God."
  },
  "20": {
   "zh": "所以凡有血氣的，沒有一個因行律法能在神面前稱義，因為律法本是叫人知罪。",
   "en": "Because by the works of the law, no flesh will be justified in his sight. For through the law comes the knowledge of sin."
  },
  "21": {
   "zh": "但如今，神的義在律法以外已經顯明出來，有律法和先知為證：",
   "en": "But now apart from the law, a righteousness of God has been revealed, being testified by the law and the prophets;"
  },
  "22": {
   "zh": "就是神的義，因信耶穌基督加給一切相信的人，並沒有分別。",
   "en": "even the righteousness of God through faith in Jesus Christ to all and on all those who believe. For there is no distinction,"
  },
  "23": {
   "zh": "因為世人都犯了罪，虧缺了神的榮耀；",
   "en": "for all have sinned, and fall short of the glory of God;"
  },
  "24": {
   "zh": "如今卻蒙神的恩典，因基督耶穌的救贖，就白白地稱義。",
   "en": "being justified freely by his grace through the redemption that is in Christ Jesus;"
  },
  "25": {
   "zh": "神設立耶穌作挽回祭，是憑著耶穌的血，藉著人的信，要顯明神的義；因為他用忍耐的心寬容人先時所犯的罪，",
   "en": "whom God sent to be an atoning sacrifice, through faith in his blood, for a demonstration of his righteousness through the passing over of prior sins, in God’s forbearance;"
  },
  "26": {
   "zh": "好在今時顯明他的義，使人知道他自己為義，也稱信耶穌的人為義。",
   "en": "to demonstrate his righteousness at this present time; that he might himself be just, and the justifier of him who has faith in Jesus."
  },
  "27": {
   "zh": "既是這樣，哪裡能誇口呢？沒有可誇的了。用何法沒有的呢？是用立功之法嗎？不是，乃用信主之法。",
   "en": "Where then is the boasting? It is excluded. By what kind of law? Of works? No, but by a law of faith."
  },
  "28": {
   "zh": "所以（有古卷：因為）我們看定了：人稱義是因著信，不在乎遵行律法。",
   "en": "We maintain therefore that a man is justified by faith apart from the works of the law."
  },
  "29": {
   "zh": "難道神只作猶太人的神嗎？不也是作外邦人的神嗎？是的，也作外邦人的神。",
   "en": "Or is God the God of Jews only? Isn’t he the God of Gentiles also? Yes, of Gentiles also,"
  },
  "30": {
   "zh": "神既是一位，他就要因信稱那受割禮的為義，也要因信稱那未受割禮的為義。",
   "en": "since indeed there is one God who will justify the circumcised by faith, and the uncircumcised through faith."
  },
  "31": {
   "zh": "這樣，我們因信廢了律法嗎？斷乎不是！更是堅固律法。",
   "en": "Do we then nullify the law through faith? May it never be! No, we establish the law."
  }
 },
 "4": {
  "1": {
   "zh": "如此說來，我們的祖宗亞伯拉罕憑著肉體得了甚麼呢？",
   "en": "What then will we say that Abraham, our forefather, has found according to the flesh?"
  },
  "2": {
   "zh": "倘若亞伯拉罕是因行為稱義，就有可誇的；只是在神面前並無可誇。",
   "en": "For if Abraham was justified by works, he has something to boast about, but not toward God."
  },
  "3": {
   "zh": "經上說甚麼呢？說：「亞伯拉罕信神，這就算為他的義。」",
   "en": "For what does the Scripture say? “Abraham believed God, and it was accounted to him for righteousness.”"
  },
  "4": {
   "zh": "做工的得工價，不算恩典，乃是該得的；",
   "en": "Now to him who works, the reward is not counted as grace, but as something owed."
  },
  "5": {
   "zh": "惟有不做工的，只信稱罪人為義的神，他的信就算為義。",
   "en": "But to him who doesn’t work, but believes in him who justifies the ungodly, his faith is accounted for righteousness."
  },
  "6": {
   "zh": "正如大衛稱那在行為以外蒙神算為義的人是有福的。",
   "en": "Even as David also pronounces blessing on the man to whom God counts righteousness apart from works,"
  },
  "7": {
   "zh": "他說：得赦免其過、遮蓋其罪的，這人是有福的。",
   "en": "“Blessed are they whose iniquities are forgiven, whose sins are covered."
  },
  "8": {
   "zh": "主不算為有罪的，這人是有福的。",
   "en": "Blessed is the man whom the Lord will by no means charge with sin.”"
  },
  "9": {
   "zh": "如此看來，這福是單加給那受割禮的人嗎？不也是加給那未受割禮的人嗎？因我們所說，亞伯拉罕的信，就算為他的義，",
   "en": "Is this blessing then pronounced on the circumcised, or on the uncircumcised also? For we say that faith was accounted to Abraham for righteousness."
  },
  "10": {
   "zh": "是怎麼算的呢？是在他受割禮的時候呢？是在他未受割禮的時候呢？不是在受割禮的時候，乃是在未受割禮的時候。",
   "en": "How then was it counted? When he was in circumcision, or in uncircumcision? Not in circumcision, but in uncircumcision."
  },
  "11": {
   "zh": "並且他受了割禮的記號，作他未受割禮的時候因信稱義的印證，叫他作一切未受割禮而信之人的父，使他們也算為義；",
   "en": "He received the sign of circumcision, a seal of the righteousness of the faith which he had while he was in uncircumcision, that he might be the father of all those who believe, though they might be in uncircumcision, that righteousness might also be accounted to them."
  },
  "12": {
   "zh": "又作受割禮之人的父，就是那些不但受割禮，並且按我們的祖宗亞伯拉罕未受割禮而信之蹤跡去行的人。",
   "en": "He is the father of circumcision to those who not only are of the circumcision, but who also walk in the steps of that faith of our father Abraham, which he had in uncircumcision."
  },
  "13": {
   "zh": "因為神應許亞伯拉罕和他後裔，必得承受世界，不是因律法，乃是因信而得的義。",
   "en": "For the promise to Abraham and to his offspring that he should be heir of the world wasn’t through the law, but through the righteousness of faith."
  },
  "14": {
   "zh": "若是屬乎律法的人才得為後嗣，信就歸於虛空，應許也就廢棄了。",
   "en": "For if those who are of the law are heirs, faith is made void, and the promise is made of no effect."
  },
  "15": {
   "zh": "因為律法是惹動忿怒的（或譯：叫人受刑的）；哪裡沒有律法，那裡就沒有過犯。",
   "en": "For the law produces wrath, for where there is no law, neither is there disobedience."
  },
  "16": {
   "zh": "所以人得為後嗣是本乎信，因此就屬乎恩，叫應許定然歸給一切後裔；不但歸給那屬乎律法的，也歸給那效法亞伯拉罕之信的。",
   "en": "For this cause it is of faith, that it may be according to grace, to the end that the promise may be sure to all the offspring, not to that only which is of the law, but to that also which is of the faith of Abraham, who is the father of us all."
  },
  "17": {
   "zh": "亞伯拉罕所信的，是那叫死人復活、使無變為有的神，他在主面前作我們世人的父。如經上所記：「我已經立你作多國的父。」",
   "en": "As it is written, “I have made you a father of many nations.” This is in the presence of him whom he believed: God, who gives life to the dead, and calls the things that are not, as though they were."
  },
  "18": {
   "zh": "他在無可指望的時候，因信仍有指望，就得以作多國的父，正如先前所說：「你的後裔將要如此。」",
   "en": "Besides hope, Abraham in hope believed, to the end that he might become a father of many nations, according to that which had been spoken, “So will your offspring be.”"
  },
  "19": {
   "zh": "他將近百歲的時候，雖然想到自己的身體如同已死，撒拉的生育已經斷絕，他的信心還是不軟弱；",
   "en": "Without being weakened in faith, he didn’t consider his own body, already having been worn out, (he being about a hundred years old), and the deadness of Sarah’s womb."
  },
  "20": {
   "zh": "並且仰望神的應許，總沒有因不信心裡起疑惑，反倒因信心裡得堅固，將榮耀歸給神，",
   "en": "Yet, looking to the promise of God, he didn’t waver through unbelief, but grew strong through faith, giving glory to God,"
  },
  "21": {
   "zh": "且滿心相信神所應許的必能做成。",
   "en": "and being fully assured that what he had promised, he was also able to perform."
  },
  "22": {
   "zh": "所以，這就算為他的義。",
   "en": "Therefore it also was “credited to him for righteousness.”"
  },
  "23": {
   "zh": "「算為他義」的這句話不是單為他寫的，",
   "en": "Now it was not written that it was accounted to him for his sake alone,"
  },
  "24": {
   "zh": "也是為我們將來得算為義之人寫的，就是我們這信神使我們的主耶穌從死裡復活的人。",
   "en": "but for our sake also, to whom it will be accounted, who believe in him who raised Jesus, our Lord, from the dead,"
  },
  "25": {
   "zh": "耶穌被交給人，是為我們的過犯；復活，是為叫我們稱義（或譯：耶穌是為我們的過犯交付了，是為我們稱義復活了）。",
   "en": "who was delivered up for our trespasses, and was raised for our justification."
  }
 },
 "5": {
  "1": {
   "zh": "我們既因信稱義，就藉著我們的主耶穌基督得與神相和。",
   "en": "Being therefore justified by faith, we have peace with God through our Lord Jesus Christ;"
  },
  "2": {
   "zh": "我們又藉著他，因信得進入現在所站的這恩典中，並且歡歡喜喜盼望神的榮耀。",
   "en": "through whom we also have our access by faith into this grace in which we stand. We rejoice in hope of the glory of God."
  },
  "3": {
   "zh": "不但如此，就是在患難中也是歡歡喜喜的；因為知道患難生忍耐，",
   "en": "Not only this, but we also rejoice in our sufferings, knowing that suffering produces perseverance;"
  },
  "4": {
   "zh": "忍耐生老練，老練生盼望；",
   "en": "and perseverance, proven character; and proven character, hope:"
  },
  "5": {
   "zh": "盼望不至於羞恥，因為所賜給我們的聖靈將神的愛澆灌在我們心裡。",
   "en": "and hope doesn’t disappoint us, because God’s love has been poured out into our hearts through the Holy Spirit who was given to us."
  },
  "6": {
   "zh": "因我們還軟弱的時候，基督就按所定的日期為罪人死。",
   "en": "For while we were yet weak, at the right time Christ died for the ungodly."
  },
  "7": {
   "zh": "為義人死，是少有的；為仁人死，或者有敢做的。",
   "en": "For one will hardly die for a righteous man. Yet perhaps for a righteous person someone would even dare to die."
  },
  "8": {
   "zh": "惟有基督在我們還作罪人的時候為我們死，神的愛就在此向我們顯明了。",
   "en": "But God commends his own love toward us, in that while we were yet sinners, Christ died for us."
  },
  "9": {
   "zh": "現在我們既靠著他的血稱義，就更要藉著他免去神的忿怒。",
   "en": "Much more then, being now justified by his blood, we will be saved from God’s wrath through him."
  },
  "10": {
   "zh": "因為我們作仇敵的時候，且藉著神兒子的死，得與神和好；既已和好，就更要因他的生得救了。",
   "en": "For if, while we were enemies, we were reconciled to God through the death of his Son, much more, being reconciled, we will be saved by his life."
  },
  "11": {
   "zh": "不但如此，我們既藉著我主耶穌基督得與神和好，也就藉著他以神為樂。",
   "en": "Not only so, but we also rejoice in God through our Lord Jesus Christ, through whom we have now received the reconciliation."
  },
  "12": {
   "zh": "這就如罪是從一人入了世界，死又是從罪來的；於是死就臨到眾人，因為眾人都犯了罪。",
   "en": "Therefore as sin entered into the world through one man, and death through sin; and so death passed to all men, because all sinned."
  },
  "13": {
   "zh": "沒有律法之先，罪已經在世上；但沒有律法，罪也不算罪。",
   "en": "For until the law, sin was in the world; but sin is not charged when there is no law."
  },
  "14": {
   "zh": "然而從亞當到摩西，死就作了王，連那些不與亞當犯一樣罪過的，也在他的權下。亞當乃是那以後要來之人的預像。",
   "en": "Nevertheless death reigned from Adam until Moses, even over those whose sins weren’t like Adam’s disobedience, who is a foreshadowing of him who was to come."
  },
  "15": {
   "zh": "只是過犯不如恩賜，若因一人的過犯，眾人都死了，何況神的恩典，與那因耶穌基督一人恩典中的賞賜，豈不更加倍地臨到眾人嗎？",
   "en": "But the free gift isn’t like the trespass. For if by the trespass of the one the many died, much more did the grace of God, and the gift by the grace of the one man, Jesus Christ, abound to the many."
  },
  "16": {
   "zh": "因一人犯罪就定罪，也不如恩賜，原來審判是由一人而定罪，恩賜乃是由許多過犯而稱義。",
   "en": "The gift is not as through one who sinned: for the judgment came by one to condemnation, but the free gift came of many trespasses to justification."
  },
  "17": {
   "zh": "若因一人的過犯，死就因這一人作了王，何況那些受洪恩又蒙所賜之義的，豈不更要因耶穌基督一人在生命中作王嗎？",
   "en": "For if by the trespass of the one, death reigned through the one; so much more will those who receive the abundance of grace and of the gift of righteousness reign in life through the one, Jesus Christ."
  },
  "18": {
   "zh": "如此說來，因一次的過犯，眾人都被定罪；照樣，因一次的義行，眾人也就被稱義得生命了。",
   "en": "So then as through one trespass, all men were condemned; even so through one act of righteousness, all men were justified to life."
  },
  "19": {
   "zh": "因一人的悖逆，眾人成為罪人；照樣，因一人的順從，眾人也成為義了。",
   "en": "For as through the one man’s disobedience many were made sinners, even so through the obedience of the one, many will be made righteous."
  },
  "20": {
   "zh": "律法本是外添的，叫過犯顯多；只是罪在哪裡顯多，恩典就更顯多了。",
   "en": "The law came in besides, that the trespass might abound; but where sin abounded, grace abounded more exceedingly;"
  },
  "21": {
   "zh": "就如罪作王叫人死；照樣，恩典也藉著義作王，叫人因我們的主耶穌基督得永生。",
   "en": "that as sin reigned in death, even so grace might reign through righteousness to eternal life through Jesus Christ our Lord."
  }
 },
 "6": {
  "1": {
   "zh": "這樣，怎麼說呢？我們可以仍在罪中、叫恩典顯多嗎？",
   "en": "What shall we say then? Shall we continue in sin, that grace may abound?"
  },
  "2": {
   "zh": "斷乎不可！我們在罪上死了的人豈可仍在罪中活著呢？",
   "en": "May it never be! We who died to sin, how could we live in it any longer?"
  },
  "3": {
   "zh": "豈不知我們這受洗歸入基督耶穌的人是受洗歸入他的死嗎？",
   "en": "Or don’t you know that all we who were baptized into Christ Jesus were baptized into his death?"
  },
  "4": {
   "zh": "所以，我們藉著洗禮歸入死，和他一同埋葬，原是叫我們一舉一動有新生的樣式，像基督藉著父的榮耀從死裡復活一樣。",
   "en": "We were buried therefore with him through baptism into death, that just as Christ was raised from the dead through the glory of the Father, so we also might walk in newness of life."
  },
  "5": {
   "zh": "我們若在他死的形狀上與他聯合，也要在他復活的形狀上與他聯合；",
   "en": "For if we have become united with him in the likeness of his death, we will also be part of his resurrection;"
  },
  "6": {
   "zh": "因為知道我們的舊人和他同釘十字架，使罪身滅絕，叫我們不再作罪的奴僕；",
   "en": "knowing this, that our old man was crucified with him, that the body of sin might be done away with, so that we would no longer be in bondage to sin."
  },
  "7": {
   "zh": "因為已死的人是脫離了罪。",
   "en": "For he who has died has been freed from sin."
  },
  "8": {
   "zh": "我們若是與基督同死，就信必與他同活。",
   "en": "But if we died with Christ, we believe that we will also live with him;"
  },
  "9": {
   "zh": "因為知道基督既從死裡復活，就不再死，死也不再作他的主了。",
   "en": "knowing that Christ, being raised from the dead, dies no more. Death no more has dominion over him!"
  },
  "10": {
   "zh": "他死是向罪死了，只有一次；他活是向神活著。",
   "en": "For the death that he died, he died to sin one time; but the life that he lives, he lives to God."
  },
  "11": {
   "zh": "這樣，你們向罪也當看自己是死的；向神在基督耶穌裡，卻當看自己是活的。",
   "en": "Thus consider yourselves also to be dead to sin, but alive to God in Christ Jesus our Lord."
  },
  "12": {
   "zh": "所以，不要容罪在你們必死的身上作王，使你們順從身子的私慾。",
   "en": "Therefore don’t let sin reign in your mortal body, that you should obey it in its lusts."
  },
  "13": {
   "zh": "也不要將你們的肢體獻給罪作不義的器具；倒要像從死裡復活的人，將自己獻給神，並將肢體作義的器具獻給神。",
   "en": "Also, do not present your members to sin as instruments of unrighteousness, but present yourselves to God, as alive from the dead, and your members as instruments of righteousness to God."
  },
  "14": {
   "zh": "罪必不能作你們的主；因你們不在律法之下，乃在恩典之下。",
   "en": "For sin will not have dominion over you. For you are not under law, but under grace."
  },
  "15": {
   "zh": "這卻怎麼樣呢？我們在恩典之下，不在律法之下，就可以犯罪嗎？斷乎不可！",
   "en": "What then? Shall we sin, because we are not under law, but under grace? May it never be!"
  },
  "16": {
   "zh": "豈不曉得你們獻上自己作奴僕，順從誰，就作誰的奴僕嗎？或作罪的奴僕，以至於死；或作順命的奴僕，以致成義。",
   "en": "Don’t you know that when you present yourselves as servants and obey someone, you are the servants of whomever you obey; whether of sin to death, or of obedience to righteousness?"
  },
  "17": {
   "zh": "感謝神！因為你們從前雖然作罪的奴僕，現今卻從心裡順服了所傳給你們道理的模範。",
   "en": "But thanks be to God, that, whereas you were bondservants of sin, you became obedient from the heart to that form of teaching to which you were delivered."
  },
  "18": {
   "zh": "你們既從罪裡得了釋放，就作了義的奴僕。",
   "en": "Being made free from sin, you became bondservants of righteousness."
  },
  "19": {
   "zh": "我因你們肉體的軟弱，就照人的常話對你們說。你們從前怎樣將肢體獻給不潔不法作奴僕，以至於不法；現今也要照樣將肢體獻給義作奴僕，以至於成聖。",
   "en": "I speak in human terms because of the weakness of your flesh, for as you presented your members as servants to uncleanness and to wickedness upon wickedness, even so now present your members as servants to righteousness for sanctification."
  },
  "20": {
   "zh": "因為你們作罪之奴僕的時候，就不被義約束了。",
   "en": "For when you were servants of sin, you were free in regard to righteousness."
  },
  "21": {
   "zh": "你們現今所看為羞恥的事，當日有甚麼果子呢？那些事的結局就是死。",
   "en": "What fruit then did you have at that time in the things of which you are now ashamed? For the end of those things is death."
  },
  "22": {
   "zh": "但現今，你們既從罪裡得了釋放，作了神的奴僕，就有成聖的果子，那結局就是永生。",
   "en": "But now, being made free from sin, and having become servants of God, you have your fruit of sanctification, and the result of eternal life."
  },
  "23": {
   "zh": "因為罪的工價乃是死；惟有神的恩賜，在我們的主基督耶穌裡，乃是永生。",
   "en": "For the wages of sin is death, but the free gift of God is eternal life in Christ Jesus our Lord."
  }
 },
 "7": {
  "1": {
   "zh": "弟兄們，我現在對明白律法的人說，你們豈不曉得律法管人是在活著的時候嗎？",
   "en": "Or don’t you know, brothers (for I speak to men who know the law), that the law has dominion over a man for as long as he lives?"
  },
  "2": {
   "zh": "就如女人有了丈夫，丈夫還活著，就被律法約束；丈夫若死了，就脫離了丈夫的律法。",
   "en": "For the woman that has a husband is bound by law to the husband while he lives, but if the husband dies, she is discharged from the law of the husband."
  },
  "3": {
   "zh": "所以丈夫活著，她若歸於別人，便叫淫婦；丈夫若死了，她就脫離了丈夫的律法，雖然歸於別人，也不是淫婦。",
   "en": "So then if, while the husband lives, she is joined to another man, she would be called an adulteress. But if the husband dies, she is free from the law, so that she is no adulteress, though she is joined to another man."
  },
  "4": {
   "zh": "我的弟兄們，這樣說來，你們藉著基督的身體，在律法上也是死了，叫你們歸於別人，就是歸於那從死裡復活的，叫我們結果子給神。",
   "en": "Therefore, my brothers, you also were made dead to the law through the body of Christ, that you would be joined to another, to him who was raised from the dead, that we might produce fruit to God."
  },
  "5": {
   "zh": "因為我們屬肉體的時候，那因律法而生的惡慾就在我們肢體中發動，以致結成死亡的果子。",
   "en": "For when we were in the flesh, the sinful passions which were through the law, worked in our members to bring out fruit to death."
  },
  "6": {
   "zh": "但我們既然在捆我們的律法上死了，現今就脫離了律法，叫我們服事主，要按著心靈（心靈：或譯聖靈）的新樣，不按著儀文的舊樣。",
   "en": "But now we have been discharged from the law, having died to that in which we were held; so that we serve in newness of the spirit, and not in oldness of the letter."
  },
  "7": {
   "zh": "這樣，我們可說甚麼呢？律法是罪嗎？斷乎不是！只是非因律法，我就不知何為罪。非律法說「不可起貪心」，我就不知何為貪心。",
   "en": "What shall we say then? Is the law sin? May it never be! However, I wouldn’t have known sin, except through the law. For I wouldn’t have known coveting, unless the law had said, “You shall not covet.”"
  },
  "8": {
   "zh": "然而，罪趁著機會，就藉著誡命叫諸般的貪心在我裡頭發動；因為沒有律法，罪是死的。",
   "en": "But sin, finding occasion through the commandment, produced in me all kinds of coveting. For apart from the law, sin is dead."
  },
  "9": {
   "zh": "我以前沒有律法是活著的；但是誡命來到，罪又活了，我就死了。",
   "en": "I was alive apart from the law once, but when the commandment came, sin revived, and I died."
  },
  "10": {
   "zh": "那本來叫人活的誡命，反倒叫我死；",
   "en": "The commandment, which was for life, this I found to be for death;"
  },
  "11": {
   "zh": "因為罪趁著機會，就藉著誡命引誘我，並且殺了我。",
   "en": "for sin, finding occasion through the commandment, deceived me, and through it killed me."
  },
  "12": {
   "zh": "這樣看來，律法是聖潔的，誡命也是聖潔、公義、良善的。",
   "en": "Therefore the law indeed is holy, and the commandment holy, and righteous, and good."
  },
  "13": {
   "zh": "既然如此，那良善的是叫我死嗎？斷乎不是！叫我死的乃是罪。但罪藉著那良善的叫我死，就顯出真是罪，叫罪因著誡命更顯出是惡極了。",
   "en": "Did then that which is good become death to me? May it never be! But sin, that it might be shown to be sin, was producing death in me through that which is good; that through the commandment sin might become exceedingly sinful."
  },
  "14": {
   "zh": "我們原曉得律法是屬乎靈的，但我是屬乎肉體的，是已經賣給罪了。",
   "en": "For we know that the law is spiritual, but I am fleshly, sold under sin."
  },
  "15": {
   "zh": "因為我所做的，我自己不明白；我所願意的，我並不做；我所恨惡的，我倒去做。",
   "en": "For I don’t know what I am doing. For I don’t practice what I desire to do; but what I hate, that I do."
  },
  "16": {
   "zh": "若我所做的，是我所不願意的，我就應承律法是善的。",
   "en": "But if what I don’t desire, that I do, I consent to the law that it is good."
  },
  "17": {
   "zh": "既是這樣，就不是我做的，乃是住在我裡頭的罪做的。",
   "en": "So now it is no more I that do it, but sin which dwells in me."
  },
  "18": {
   "zh": "我也知道，在我裡頭，就是我肉體之中，沒有良善。因為，立志為善由得我，只是行出來由不得我。",
   "en": "For I know that in me, that is, in my flesh, dwells no good thing. For desire is present with me, but I don’t find it doing that which is good."
  },
  "19": {
   "zh": "故此，我所願意的善，我反不做；我所不願意的惡，我倒去做。",
   "en": "For the good which I desire, I don’t do; but the evil which I don’t desire, that I practice."
  },
  "20": {
   "zh": "若我去做所不願意做的，就不是我做的，乃是住在我裡頭的罪做的。",
   "en": "But if what I don’t desire, that I do, it is no more I that do it, but sin which dwells in me."
  },
  "21": {
   "zh": "我覺得有個律，就是我願意為善的時候，便有惡與我同在。",
   "en": "I find then the law, that, to me, while I desire to do good, evil is present."
  },
  "22": {
   "zh": "因為按著我裡面的意思（原文是人），我是喜歡神的律；",
   "en": "For I delight in God’s law after the inward man,"
  },
  "23": {
   "zh": "但我覺得肢體中另有個律和我心中的律交戰，把我擄去，叫我附從那肢體中犯罪的律。",
   "en": "but I see a different law in my members, warring against the law of my mind, and bringing me into captivity under the law of sin which is in my members."
  },
  "24": {
   "zh": "我真是苦啊！誰能救我脫離這取死的身體呢？",
   "en": "What a wretched man I am! Who will deliver me out of the body of this death?"
  },
  "25": {
   "zh": "感謝神，靠著我們的主耶穌基督就能脫離了。這樣看來，我以內心順服神的律，我肉體卻順服罪的律了。",
   "en": "I thank God through Jesus Christ, our Lord! So then with the mind, I myself serve God’s law, but with the flesh, the sin’s law."
  }
 },
 "8": {
  "1": {
   "zh": "如今，那些在基督耶穌裡的就不定罪了。",
   "en": "There is therefore now no condemnation to those who are in Christ Jesus, who don’t walk according to the flesh, but according to the Spirit."
  },
  "2": {
   "zh": "因為賜生命聖靈的律，在基督耶穌裡釋放了我，使我脫離罪和死的律了。",
   "en": "For the law of the Spirit of life in Christ Jesus made me free from the law of sin and of death."
  },
  "3": {
   "zh": "律法既因肉體軟弱，有所不能行的，神就差遣自己的兒子，成為罪身的形狀，作了贖罪祭，在肉體中定了罪案，",
   "en": "For what the law couldn’t do, in that it was weak through the flesh, God did, sending his own Son in the likeness of sinful flesh and for sin, he condemned sin in the flesh;"
  },
  "4": {
   "zh": "使律法的義成就在我們這不隨從肉體、只隨從聖靈的人身上。",
   "en": "that the ordinance of the law might be fulfilled in us, who walk not after the flesh, but after the Spirit."
  },
  "5": {
   "zh": "因為，隨從肉體的人體貼肉體的事；隨從聖靈的人體貼聖靈的事。",
   "en": "For those who live according to the flesh set their minds on the things of the flesh, but those who live according to the Spirit, the things of the Spirit."
  },
  "6": {
   "zh": "體貼肉體的，就是死；體貼聖靈的，乃是生命、平安。",
   "en": "For the mind of the flesh is death, but the mind of the Spirit is life and peace;"
  },
  "7": {
   "zh": "原來體貼肉體的，就是與神為仇；因為不服神的律法，也是不能服，",
   "en": "because the mind of the flesh is hostile towards God; for it is not subject to God’s law, neither indeed can it be."
  },
  "8": {
   "zh": "而且屬肉體的人不能得神的喜歡。",
   "en": "Those who are in the flesh can’t please God."
  },
  "9": {
   "zh": "如果神的靈住在你們心裡，你們就不屬肉體，乃屬聖靈了。人若沒有基督的靈，就不是屬基督的。",
   "en": "But you are not in the flesh but in the Spirit, if it is so that the Spirit of God dwells in you. But if any man doesn’t have the Spirit of Christ, he is not his."
  },
  "10": {
   "zh": "基督若在你們心裡，身體就因罪而死，心靈卻因義而活。",
   "en": "If Christ is in you, the body is dead because of sin, but the spirit is alive because of righteousness."
  },
  "11": {
   "zh": "然而，叫耶穌從死裡復活者的靈若住在你們心裡，那叫基督耶穌從死裡復活的，也必藉著住在你們心裡的聖靈，使你們必死的身體又活過來。",
   "en": "But if the Spirit of him who raised up Jesus from the dead dwells in you, he who raised up Christ Jesus from the dead will also give life to your mortal bodies through his Spirit who dwells in you."
  },
  "12": {
   "zh": "弟兄們，這樣看來，我們並不是欠肉體的債去順從肉體活著。",
   "en": "So then, brothers, we are debtors, not to the flesh, to live after the flesh."
  },
  "13": {
   "zh": "你們若順從肉體活著，必要死；若靠著聖靈治死身體的惡行，必要活著。",
   "en": "For if you live after the flesh, you must die; but if by the Spirit you put to death the deeds of the body, you will live."
  },
  "14": {
   "zh": "因為凡被神的靈引導的，都是神的兒子。",
   "en": "For as many as are led by the Spirit of God, these are children of God."
  },
  "15": {
   "zh": "你們所受的，不是奴僕的心，仍舊害怕；所受的，乃是兒子的心，因此我們呼叫：「阿爸！父！」",
   "en": "For you didn’t receive the spirit of bondage again to fear, but you received the Spirit of adoption, by whom we cry, “Abba! Father!”"
  },
  "16": {
   "zh": "聖靈與我們的心同證我們是神的兒女；",
   "en": "The Spirit himself testifies with our spirit that we are children of God;"
  },
  "17": {
   "zh": "既是兒女，便是後嗣，就是神的後嗣，和基督同作後嗣。如果我們和他一同受苦，也必和他一同得榮耀。",
   "en": "and if children, then heirs; heirs of God, and joint heirs with Christ; if indeed we suffer with him, that we may also be glorified with him."
  },
  "18": {
   "zh": "我想，現在的苦楚若比起將來要顯於我們的榮耀就不足介意了。",
   "en": "For I consider that the sufferings of this present time are not worthy to be compared with the glory which will be revealed toward us."
  },
  "19": {
   "zh": "受造之物切望等候神的眾子顯出來。",
   "en": "For the creation waits with eager expectation for the children of God to be revealed."
  },
  "20": {
   "zh": "因為受造之物服在虛空之下，不是自己願意，乃是因那叫他如此的。",
   "en": "For the creation was subjected to vanity, not of its own will, but because of him who subjected it, in hope"
  },
  "21": {
   "zh": "但受造之物仍然指望脫離敗壞的轄制，得享（享：原文是入）神兒女自由的榮耀。",
   "en": "that the creation itself also will be delivered from the bondage of decay into the liberty of the glory of the children of God."
  },
  "22": {
   "zh": "我們知道，一切受造之物一同歎息，勞苦，直到如今。",
   "en": "For we know that the whole creation groans and travails in pain together until now."
  },
  "23": {
   "zh": "不但如此，就是我們這有聖靈初結果子的，也是自己心裡歎息，等候得著兒子的名分，乃是我們的身體得贖。",
   "en": "Not only so, but ourselves also, who have the first fruits of the Spirit, even we ourselves groan within ourselves, waiting for adoption, the redemption of our body."
  },
  "24": {
   "zh": "我們得救是在乎盼望；只是所見的盼望不是盼望，誰還盼望他所見的呢（有古卷：人所看見的何必再盼望呢）？",
   "en": "For we were saved in hope, but hope that is seen is not hope. For who hopes for that which he sees?"
  },
  "25": {
   "zh": "但我們若盼望那所不見的，就必忍耐等候。",
   "en": "But if we hope for that which we don’t see, we wait for it with patience."
  },
  "26": {
   "zh": "況且，我們的軟弱有聖靈幫助；我們本不曉得當怎樣禱告，只是聖靈親自用說不出來的歎息替我們禱告。",
   "en": "In the same way, the Spirit also helps our weaknesses, for we don’t know how to pray as we ought. But the Spirit himself makes intercession for us with groanings which can’t be uttered."
  },
  "27": {
   "zh": "鑒察人心的，曉得聖靈的意思，因為聖靈照著神的旨意替聖徒祈求。",
   "en": "He who searches the hearts knows what is on the Spirit’s mind, because he makes intercession for the saints according to God."
  },
  "28": {
   "zh": "我們曉得萬事都互相效力，叫愛神的人得益處，就是按他旨意被召的人。",
   "en": "We know that all things work together for good for those who love God, to those who are called according to his purpose."
  },
  "29": {
   "zh": "因為他預先所知道的人，就預先定下效法他兒子的模樣，使他兒子在許多弟兄中作長子。",
   "en": "For whom he foreknew, he also predestined to be conformed to the image of his Son, that he might be the firstborn among many brothers."
  },
  "30": {
   "zh": "預先所定下的人又召他們來；所召來的人又稱他們為義；所稱為義的人又叫他們得榮耀。",
   "en": "Whom he predestined, those he also called. Whom he called, those he also justified. Whom he justified, those he also glorified."
  },
  "31": {
   "zh": "既是這樣，還有甚麼說的呢？神若幫助我們，誰能敵擋我們呢？",
   "en": "What then shall we say about these things? If God is for us, who can be against us?"
  },
  "32": {
   "zh": "神既不愛惜自己的兒子，為我們眾人捨了，豈不也把萬物和他一同白白地賜給我們嗎？",
   "en": "He who didn’t spare his own Son, but delivered him up for us all, how would he not also with him freely give us all things?"
  },
  "33": {
   "zh": "誰能控告神所揀選的人呢？有神稱他們為義了（或譯：是稱他們為義的神嗎）。",
   "en": "Who could bring a charge against God’s chosen ones? It is God who justifies."
  },
  "34": {
   "zh": "誰能定他們的罪呢？有基督耶穌已經死了，而且從死裡復活，現今在神的右邊，也替我們祈求（有基督....或譯：是已經死了，而且從死裡復活，現今在神的右邊，也替我們祈求的基督耶穌嗎）。",
   "en": "Who is he who condemns? It is Christ who died, yes rather, who was raised from the dead, who is at the right hand of God, who also makes intercession for us."
  },
  "35": {
   "zh": "誰能使我們與基督的愛隔絕呢？難道是患難嗎？是困苦嗎？是逼迫嗎？是飢餓嗎？是赤身露體嗎？是危險嗎？是刀劍嗎？",
   "en": "Who shall separate us from the love of Christ? Could oppression, or anguish, or persecution, or famine, or nakedness, or peril, or sword?"
  },
  "36": {
   "zh": "如經上所記：我們為你的緣故終日被殺；人看我們如將宰的羊。",
   "en": "Even as it is written, “For your sake we are killed all day long. We were accounted as sheep for the slaughter.”"
  },
  "37": {
   "zh": "然而，靠著愛我們的主，在這一切的事上已經得勝有餘了。",
   "en": "No, in all these things, we are more than conquerors through him who loved us."
  },
  "38": {
   "zh": "因為我深信無論是死，是生，是天使，是掌權的，是有能的，是現在的事，是將來的事，",
   "en": "For I am persuaded that neither death, nor life, nor angels, nor principalities, nor things present, nor things to come, nor powers,"
  },
  "39": {
   "zh": "是高處的，是低處的，是別的受造之物，都不能叫我們與神的愛隔絕；這愛是在我們的主基督耶穌裡的。",
   "en": "nor height, nor depth, nor any other created thing, will be able to separate us from God’s love, which is in Christ Jesus our Lord."
  }
 },
 "9": {
  "1": {
   "zh": "我在基督裡說真話，並不謊言，有我良心被聖靈感動，給我作見證：",
   "en": "I tell the truth in Christ. I am not lying, my conscience testifying with me in the Holy Spirit,"
  },
  "2": {
   "zh": "我是大有憂愁，心裡時常傷痛；",
   "en": "that I have great sorrow and unceasing pain in my heart."
  },
  "3": {
   "zh": "為我弟兄，我骨肉之親，就是自己被咒詛，與基督分離，我也願意。",
   "en": "For I could wish that I myself were accursed from Christ for my brothers’ sake, my relatives according to the flesh,"
  },
  "4": {
   "zh": "他們是以色列人；那兒子的名分、榮耀、諸約、律法、禮儀、應許都是他們的。",
   "en": "who are Israelites; whose is the adoption, the glory, the covenants, the giving of the law, the service, and the promises;"
  },
  "5": {
   "zh": "列祖就是他們的祖宗；按肉體說，基督也是從他們出來的。他是在萬有之上，永遠可稱頌的神。阿們！",
   "en": "of whom are the fathers, and from whom is Christ as concerning the flesh, who is over all, God, blessed forever. Amen."
  },
  "6": {
   "zh": "這不是說神的話落了空。因為從以色列生的不都是以色列人，",
   "en": "But it is not as though the word of God has come to nothing. For they are not all Israel, that are of Israel."
  },
  "7": {
   "zh": "也不因為是亞伯拉罕的後裔就都作他的兒女；惟獨「從以撒生的才要稱為你的後裔。」",
   "en": "Neither, because they are Abraham’s offspring, are they all children. But, “your offspring will be accounted as from Isaac.”"
  },
  "8": {
   "zh": "這就是說，肉身所生的兒女不是神的兒女，惟獨那應許的兒女才算是後裔。",
   "en": "That is, it is not the children of the flesh who are children of God, but the children of the promise are counted as heirs."
  },
  "9": {
   "zh": "因為所應許的話是這樣說：「到明年這時候我要來，撒拉必生一個兒子。」",
   "en": "For this is a word of promise, “At the appointed time I will come, and Sarah will have a son.”"
  },
  "10": {
   "zh": "不但如此，還有利百加，既從一個人，就是從我們的祖宗以撒懷了孕，",
   "en": "Not only so, but Rebekah also conceived by one, by our father Isaac."
  },
  "11": {
   "zh": "（雙子還沒有生下來，善惡還沒有做出來，只因要顯明神揀選人的旨意，不在乎人的行為，乃在乎召人的主。）",
   "en": "For being not yet born, neither having done anything good or bad, that the purpose of God according to election might stand, not of works, but of him who calls,"
  },
  "12": {
   "zh": "神就對利百加說：「將來，大的要服事小的。」",
   "en": "it was said to her, “The elder will serve the younger.”"
  },
  "13": {
   "zh": "正如經上所記：雅各是我所愛的；以掃是我所惡的。",
   "en": "Even as it is written, “Jacob I loved, but Esau I hated.”"
  },
  "14": {
   "zh": "這樣，我們可說甚麼呢？難道神有甚麼不公平嗎？斷乎沒有！",
   "en": "What shall we say then? Is there unrighteousness with God? May it never be!"
  },
  "15": {
   "zh": "因他對摩西說：我要憐憫誰就憐憫誰，要恩待誰就恩待誰。",
   "en": "For he said to Moses, “I will have mercy on whom I have mercy, and I will have compassion on whom I have compassion.”"
  },
  "16": {
   "zh": "據此看來，這不在乎那定意的，也不在乎那奔跑的，只在乎發憐憫的神。",
   "en": "So then it is not of him who wills, nor of him who runs, but of God who has mercy."
  },
  "17": {
   "zh": "因為經上有話向法老說：「我將你興起來，特要在你身上彰顯我的權能，並要使我的名傳遍天下。」",
   "en": "For the Scripture says to Pharaoh, “For this very purpose I caused you to be raised up, that I might show in you my power, and that my name might be proclaimed in all the earth.”"
  },
  "18": {
   "zh": "如此看來，神要憐憫誰就憐憫誰，要叫誰剛硬就叫誰剛硬。",
   "en": "So then, he has mercy on whom he desires, and he hardens whom he desires."
  },
  "19": {
   "zh": "這樣，你必對我說：「他為甚麼還指責人呢？有誰抗拒他的旨意呢？」",
   "en": "You will say then to me, “Why does he still find fault? For who withstands his will?”"
  },
  "20": {
   "zh": "你這個人哪，你是誰，竟敢向神強嘴呢？受造之物豈能對造他的說：「你為甚麼這樣造我呢？」",
   "en": "But indeed, O man, who are you to reply against God? Will the thing formed ask him who formed it, “Why did you make me like this?”"
  },
  "21": {
   "zh": "窯匠難道沒有權柄從一團泥裡拿一塊做成貴重的器皿，又拿一塊做成卑賤的器皿嗎？",
   "en": "Or hasn’t the potter a right over the clay, from the same lump to make one part a vessel for honor, and another for dishonor?"
  },
  "22": {
   "zh": "倘若神要顯明他的忿怒，彰顯他的權能，就多多忍耐寬容那可怒、預備遭毀滅的器皿，",
   "en": "What if God, willing to show his wrath, and to make his power known, endured with much patience vessels of wrath prepared for destruction,"
  },
  "23": {
   "zh": "又要將他豐盛的榮耀彰顯在那蒙憐憫、早預備得榮耀的器皿上。",
   "en": "and that he might make known the riches of his glory on vessels of mercy, which he prepared beforehand for glory,"
  },
  "24": {
   "zh": "這器皿就是我們被神所召的，不但是從猶太人中，也是從外邦人中。這有甚麼不可呢？",
   "en": "us, whom he also called, not from the Jews only, but also from the Gentiles?"
  },
  "25": {
   "zh": "就像神在何西阿書上說：那本來不是我子民的，我要稱為「我的子民」；本來不是蒙愛的，我要稱為「蒙愛的」。",
   "en": "As he says also in Hosea, “I will call them ‘my people,’ which were not my people; and her ‘beloved,’ who was not beloved.”"
  },
  "26": {
   "zh": "從前在甚麼地方對他們說：你們不是我的子民，將來就在那裡稱他們為「永生神的兒子」。",
   "en": "“It will be that in the place where it was said to them, ‘You are not my people,’ There they will be called ‘children of the living God.’”"
  },
  "27": {
   "zh": "以賽亞指著以色列人喊著說：「以色列人雖多如海沙，得救的不過是剩下的餘數；",
   "en": "Isaiah cries concerning Israel, “If the number of the children of Israel are as the sand of the sea, it is the remnant who will be saved;"
  },
  "28": {
   "zh": "因為主要在世上施行他的話，叫他的話都成全，速速地完結。」",
   "en": "for He will finish the work and cut it short in righteousness, because the LORD will make a short work upon the earth.”"
  },
  "29": {
   "zh": "又如以賽亞先前說過：若不是萬軍之主給我們存留餘種，我們早已像所多瑪、蛾摩拉的樣子了。",
   "en": "As Isaiah has said before, “Unless the Lord of Armies had left us a seed, we would have become like Sodom, and would have been made like Gomorrah.”"
  },
  "30": {
   "zh": "這樣，我們可說甚麼呢？那本來不追求義的外邦人反得了義，就是因信而得的義。",
   "en": "What shall we say then? That the Gentiles, who didn’t follow after righteousness, attained to righteousness, even the righteousness which is of faith;"
  },
  "31": {
   "zh": "但以色列人追求律法的義，反得不著律法的義。",
   "en": "but Israel, following after a law of righteousness, didn’t arrive at the law of righteousness."
  },
  "32": {
   "zh": "這是甚麼緣故呢？是因為他們不憑著信心求，只憑著行為求；他們正跌在那絆腳石上。",
   "en": "Why? Because they didn’t seek it by faith, but as it were by works of the law. They stumbled over the stumbling stone;"
  },
  "33": {
   "zh": "就如經上所記：我在錫安放一塊絆腳的石頭，跌人的磐石；信靠他的人必不至於羞愧。",
   "en": "even as it is written, “Behold, I lay in Zion a stumbling stone and a rock of offense; and no one who believes in him will be disappointed.”"
  }
 },
 "10": {
  "1": {
   "zh": "弟兄們，我心裡所願的，向神所求的，是要以色列人得救。",
   "en": "Brothers, my heart’s desire and my prayer to God is for Israel, that they may be saved."
  },
  "2": {
   "zh": "我可以證明，他們向神有熱心，但不是按著真知識；",
   "en": "For I testify about them that they have a zeal for God, but not according to knowledge."
  },
  "3": {
   "zh": "因為不知道神的義，想要立自己的義，就不服神的義了。",
   "en": "For being ignorant of God’s righteousness, and seeking to establish their own righteousness, they didn’t subject themselves to the righteousness of God."
  },
  "4": {
   "zh": "律法的總結就是基督，使凡信他的都得著義。",
   "en": "For Christ is the fulfillment of the law for righteousness to everyone who believes."
  },
  "5": {
   "zh": "摩西寫著說：「人若行那出於律法的義，就必因此活著。」",
   "en": "For Moses writes about the righteousness of the law, “The one who does them will live by them.”"
  },
  "6": {
   "zh": "惟有出於信心的義如此說：「你不要心裡說：誰要升到天上去呢？（就是要領下基督來；）",
   "en": "But the righteousness which is of faith says this, “Don’t say in your heart, ‘Who will ascend into heaven?’ (that is, to bring Christ down);"
  },
  "7": {
   "zh": "誰要下到陰間去呢？（就是要領基督從死裡上來。）」",
   "en": "or, ‘Who will descend into the abyss?’ (that is, to bring Christ up from the dead.)”"
  },
  "8": {
   "zh": "他到底怎麼說呢？他說：這道離你不遠，正在你口裡，在你心裡─（就是我們所傳信主的道。）",
   "en": "But what does it say? “The word is near you, in your mouth, and in your heart”; that is, the word of faith, which we preach:"
  },
  "9": {
   "zh": "你若口裡認耶穌為主，心裡信神叫他從死裡復活，就必得救。",
   "en": "that if you will confess with your mouth that Jesus is Lord, and believe in your heart that God raised him from the dead, you will be saved."
  },
  "10": {
   "zh": "因為，人心裡相信就可以稱義，口裡承認就可以得救。",
   "en": "For with the heart, one believes unto righteousness; and with the mouth confession is made unto salvation."
  },
  "11": {
   "zh": "經上說：「凡信他的人必不至於羞愧。」",
   "en": "For the Scripture says, “Whoever believes in him will not be disappointed.”"
  },
  "12": {
   "zh": "猶太人和希臘人並沒有分別，因為眾人同有一位主；他也厚待一切求告他的人。",
   "en": "For there is no distinction between Jew and Greek; for the same Lord is Lord of all, and is rich to all who call on him."
  },
  "13": {
   "zh": "因為「凡求告主名的就必得救」。",
   "en": "For, “Whoever will call on the name of the Lord will be saved.”"
  },
  "14": {
   "zh": "然而，人未曾信他，怎能求他呢？未曾聽見他，怎能信他呢？沒有傳道的，怎能聽見呢？",
   "en": "How then will they call on him in whom they have not believed? How will they believe in him whom they have not heard? How will they hear without a preacher?"
  },
  "15": {
   "zh": "若沒有奉差遣，怎能傳道呢？如經上所記：「報福音、傳喜信的人，他們的腳蹤何等佳美！」",
   "en": "And how will they preach unless they are sent? As it is written: “How beautiful are the feet of those who preach the Good News of peace, who bring glad tidings of good things!”"
  },
  "16": {
   "zh": "只是人沒有都聽從福音，因為以賽亞說：「主啊，我們所傳的有誰信呢？」",
   "en": "But they didn’t all listen to the glad news. For Isaiah says, “Lord, who has believed our report?”"
  },
  "17": {
   "zh": "可見，信道是從聽道來的，聽道是從基督的話來的。",
   "en": "So faith comes by hearing, and hearing by the word of God."
  },
  "18": {
   "zh": "但我說，人沒有聽見嗎？誠然聽見了。他們的聲音傳遍天下；他們的言語傳到地極。",
   "en": "But I say, didn’t they hear? Yes, most certainly, “Their sound went out into all the earth, their words to the ends of the world.”"
  },
  "19": {
   "zh": "我再說，以色列人不知道嗎？先有摩西說：我要用那不成子民的惹動你們的憤恨；我要用那無知的民觸動你們的怒氣。",
   "en": "But I ask, didn’t Israel know? First Moses says, “I will provoke you to jealousy with that which is no nation, with a nation void of understanding I will make you angry.”"
  },
  "20": {
   "zh": "又有以賽亞放膽說：沒有尋找我的，我叫他們遇見；沒有訪問我的，我向他們顯現。",
   "en": "Isaiah is very bold, and says, “I was found by those who didn’t seek me. I was revealed to those who didn’t ask for me.”"
  },
  "21": {
   "zh": "至於以色列人，他說：「我整天伸手招呼那悖逆頂嘴的百姓。」",
   "en": "But as to Israel he says, “All day long I stretched out my hands to a disobedient and contrary people.”"
  }
 },
 "11": {
  "1": {
   "zh": "我且說，神棄絕了他的百姓嗎？斷乎沒有！因為我也是以色列人，亞伯拉罕的後裔，屬便雅憫支派的。",
   "en": "I ask then, did God reject his people? May it never be! For I also am an Israelite, a descendant of Abraham, of the tribe of Benjamin."
  },
  "2": {
   "zh": "神並沒有棄絕他預先所知道的百姓。你們豈不曉得經上論到以利亞是怎麼說的呢？他在神面前怎樣控告以色列人說：",
   "en": "God didn’t reject his people, which he foreknew. Or don’t you know what the Scripture says about Elijah? How he pleads with God against Israel:"
  },
  "3": {
   "zh": "「主啊，他們殺了你的先知，拆了你的祭壇，只剩下我一個人；他們還要尋索我的命。」",
   "en": "“Lord, they have killed your prophets, they have broken down your altars; and I am left alone, and they seek my life.”"
  },
  "4": {
   "zh": "神的回話是怎麼說的呢？他說：「我為自己留下七千人，是未曾向巴力屈膝的。」",
   "en": "But how does God answer him? “I have reserved for myself seven thousand men, who have not bowed the knee to Baal.”"
  },
  "5": {
   "zh": "如今也是這樣，照著揀選的恩典，還有所留的餘數。",
   "en": "Even so then at this present time also there is a remnant according to the election of grace."
  },
  "6": {
   "zh": "既是出於恩典，就不在乎行為；不然，恩典就不是恩典了。",
   "en": "And if by grace, then it is no longer of works; otherwise grace is no longer grace. But if it is of works, it is no longer grace; otherwise work is no longer work."
  },
  "7": {
   "zh": "這是怎麼樣呢？以色列人所求的，他們沒有得著。惟有蒙揀選的人得著了；其餘的就成了頑梗不化的。",
   "en": "What then? That which Israel seeks for, that he didn’t obtain, but the chosen ones obtained it, and the rest were hardened."
  },
  "8": {
   "zh": "如經上所記：神給他們昏迷的心，眼睛不能看見，耳朵不能聽見，直到今日。",
   "en": "According as it is written, “God gave them a spirit of stupor, eyes that they should not see, and ears that they should not hear, to this very day.”"
  },
  "9": {
   "zh": "大衛也說：願他們的筵席變為網羅，變為機檻，變為絆腳石，作他們的報應。",
   "en": "David says, “Let their table be made a snare, and a trap, a stumbling block, and a retribution to them."
  },
  "10": {
   "zh": "願他們的眼睛昏矇，不得看見；願你時常彎下他們的腰。",
   "en": "Let their eyes be darkened, that they may not see. Bow down their back always.”"
  },
  "11": {
   "zh": "我且說，他們失腳是要他們跌倒嗎？斷乎不是！反倒因他們的過失，救恩便臨到外邦人，要激動他們發憤。",
   "en": "I ask then, did they stumble that they might fall? May it never be! But by their fall salvation has come to the Gentiles, to provoke them to jealousy."
  },
  "12": {
   "zh": "若他們的過失為天下的富足，他們的缺乏為外邦人的富足，何況他們的豐滿呢？",
   "en": "Now if their fall is the riches of the world, and their loss the riches of the Gentiles; how much more their fullness?"
  },
  "13": {
   "zh": "我對你們外邦人說這話；因我是外邦人的使徒，所以敬重（原文是榮耀）我的職分，",
   "en": "For I speak to you who are Gentiles. Since then as I am an apostle to Gentiles, I glorify my ministry;"
  },
  "14": {
   "zh": "或者可以激動我骨肉之親發憤，好救他們一些人。",
   "en": "if by any means I may provoke to jealousy those who are my flesh, and may save some of them."
  },
  "15": {
   "zh": "若他們被丟棄，天下就得與神和好，他們被收納，豈不是死而復生嗎？",
   "en": "For if the rejection of them is the reconciling of the world, what would their acceptance be, but life from the dead?"
  },
  "16": {
   "zh": "所獻的新麵若是聖潔，全團也就聖潔了；樹根若是聖潔，樹枝也就聖潔了。",
   "en": "If the first fruit is holy, so is the lump. If the root is holy, so are the branches."
  },
  "17": {
   "zh": "若有幾根枝子被折下來，你這野橄欖得接在其中，一同得著橄欖根的肥汁，",
   "en": "But if some of the branches were broken off, and you, being a wild olive, were grafted in among them, and became partaker with them of the root and of the richness of the olive tree;"
  },
  "18": {
   "zh": "你就不可向舊枝子誇口；若是誇口，當知道不是你托著根，乃是根托著你。",
   "en": "don’t boast over the branches. But if you boast, it is not you who support the root, but the root supports you."
  },
  "19": {
   "zh": "你若說，那枝子被折下來是特為叫我接上。",
   "en": "You will say then, “Branches were broken off, that I might be grafted in.”"
  },
  "20": {
   "zh": "不錯！他們因為不信，所以被折下來；你因為信，所以立得住；你不可自高，反要懼怕。",
   "en": "True; by their unbelief they were broken off, and you stand by your faith. Don’t be conceited, but fear;"
  },
  "21": {
   "zh": "神既不愛惜原來的枝子，也必不愛惜你。",
   "en": "for if God didn’t spare the natural branches, neither will he spare you."
  },
  "22": {
   "zh": "可見，神的恩慈和嚴厲向那跌倒的人是嚴厲的，向你是有恩慈的，只要你長久在他的恩慈裡；不然，你也要被砍下來。",
   "en": "See then the goodness and severity of God. Toward those who fell, severity; but toward you, goodness, if you continue in his goodness; otherwise you also will be cut off."
  },
  "23": {
   "zh": "而且他們若不是長久不信，仍要被接上，因為神能夠把他們重新接上。",
   "en": "They also, if they don’t continue in their unbelief, will be grafted in, for God is able to graft them in again."
  },
  "24": {
   "zh": "你是從那天生的野橄欖上砍下來的，尚且逆著性得接在好橄欖上，何況這本樹的枝子，要接在本樹上呢！",
   "en": "For if you were cut out of that which is by nature a wild olive tree, and were grafted contrary to nature into a good olive tree, how much more will these, which are the natural branches, be grafted into their own olive tree?"
  },
  "25": {
   "zh": "弟兄們，我不願意你們不知道這奧祕（恐怕你們自以為聰明），就是以色列人有幾分是硬心的，等到外邦人的數目添滿了，",
   "en": "For I don’t desire you to be ignorant, brothers, of this mystery, so that you won’t be wise in your own conceits, that a partial hardening has happened to Israel, until the fullness of the Gentiles has come in,"
  },
  "26": {
   "zh": "於是以色列全家都要得救。如經上所記：必有一位救主從錫安出來，要消除雅各家的一切罪惡；",
   "en": "and so all Israel will be saved. Even as it is written, “There will come out of Zion the Deliverer, and he will turn away ungodliness from Jacob."
  },
  "27": {
   "zh": "又說：我除去他們罪的時候，這就是我與他們所立的約。",
   "en": "This is my covenant with them, when I will take away their sins.”"
  },
  "28": {
   "zh": "就著福音說，他們為你們的緣故是仇敵；就著揀選說，他們為列祖的緣故是蒙愛的。",
   "en": "Concerning the Good News, they are enemies for your sake. But concerning the election, they are beloved for the fathers’ sake."
  },
  "29": {
   "zh": "因為神的恩賜和選召是沒有後悔的。",
   "en": "For the gifts and the calling of God are irrevocable."
  },
  "30": {
   "zh": "你們從前不順服神，如今因他們的不順服，你們倒蒙了憐恤。",
   "en": "For as you in time past were disobedient to God, but now have obtained mercy by their disobedience,"
  },
  "31": {
   "zh": "這樣，他們也是不順服，叫他們因著施給你們的憐恤，現在也就蒙憐恤。",
   "en": "even so these also have now been disobedient, that by the mercy shown to you they may also obtain mercy."
  },
  "32": {
   "zh": "因為神將眾人都圈在不順服之中，特意要憐恤眾人。",
   "en": "For God has shut up all to disobedience, that he might have mercy on all."
  },
  "33": {
   "zh": "深哉，神豐富的智慧和知識！他的判斷何其難測！他的蹤跡何其難尋！",
   "en": "Oh the depth of the riches both of the wisdom and the knowledge of God! How unsearchable are his judgments, and his ways past tracing out!"
  },
  "34": {
   "zh": "誰知道主的心？誰作過他的謀士呢？",
   "en": "“For who has known the mind of the Lord? Or who has been his counselor?”"
  },
  "35": {
   "zh": "誰是先給了他，使他後來償還呢？",
   "en": "“Or who has first given to him, and it will be repaid to him again?”"
  },
  "36": {
   "zh": "因為萬有都是本於他，倚靠他，歸於他。願榮耀歸給他，直到永遠。阿們！",
   "en": "For of him, and through him, and to him, are all things. To him be the glory for ever! Amen."
  }
 },
 "12": {
  "1": {
   "zh": "所以，弟兄們，我以神的慈悲勸你們，將身體獻上，當作活祭，是聖潔的，是神所喜悅的；你們如此事奉乃是理所當然的。",
   "en": "Therefore I urge you, brothers, by the mercies of God, to present your bodies a living sacrifice, holy, acceptable to God, which is your spiritual service."
  },
  "2": {
   "zh": "不要效法這個世界，只要心意更新而變化，叫你們察驗何為神的善良、純全、可喜悅的旨意。",
   "en": "Don’t be conformed to this world, but be transformed by the renewing of your mind, so that you may prove what is the good, well-pleasing, and perfect will of God."
  },
  "3": {
   "zh": "我憑著所賜我的恩對你們各人說：不要看自己過於所當看的；要照著神所分給各人信心的大小，看得合乎中道。",
   "en": "For I say, through the grace that was given me, to every man who is among you, not to think of himself more highly than he ought to think; but to think reasonably, as God has apportioned to each person a measure of faith."
  },
  "4": {
   "zh": "正如我們一個身子上有好些肢體，肢體也不都是一樣的用處。",
   "en": "For even as we have many members in one body, and all the members don’t have the same function,"
  },
  "5": {
   "zh": "我們這許多人，在基督裡成為一身，互相聯絡作肢體，也是如此。",
   "en": "so we, who are many, are one body in Christ, and individually members one of another."
  },
  "6": {
   "zh": "按我們所得的恩賜，各有不同。或說預言，就當照著信心的程度說預言；",
   "en": "Having gifts differing according to the grace that was given to us, if prophecy, let us prophesy according to the proportion of our faith;"
  },
  "7": {
   "zh": "或作執事，就當專一執事；或作教導的，就當專一教導；",
   "en": "or service, let us give ourselves to service; or he who teaches, to his teaching;"
  },
  "8": {
   "zh": "或作勸化的，就當專一勸化；施捨的，就當誠實；治理的，就當殷勤；憐憫人的，就當甘心。",
   "en": "or he who exhorts, to his exhorting: he who gives, let him do it with generosity; he who rules, with diligence; he who shows mercy, with cheerfulness."
  },
  "9": {
   "zh": "愛人不可虛假。惡，要厭惡；善，要親近。",
   "en": "Let love be without hypocrisy. Abhor that which is evil. Cling to that which is good."
  },
  "10": {
   "zh": "愛弟兄，要彼此親熱；恭敬人，要彼此推讓。",
   "en": "In love of the brothers be tenderly affectionate to one another; in honor preferring one another;"
  },
  "11": {
   "zh": "殷勤，不可懶惰；要心裡火熱，常常服事主。",
   "en": "not lagging in diligence; fervent in spirit; serving the Lord;"
  },
  "12": {
   "zh": "在指望中要喜樂；在患難中要忍耐；禱告要恆切。",
   "en": "rejoicing in hope; enduring in troubles; continuing steadfastly in prayer;"
  },
  "13": {
   "zh": "聖徒缺乏，要幫補；客，要一味地款待。",
   "en": "contributing to the needs of the saints; given to hospitality."
  },
  "14": {
   "zh": "逼迫你們的，要給他們祝福；只要祝福，不可咒詛。",
   "en": "Bless those who persecute you; bless, and don’t curse."
  },
  "15": {
   "zh": "與喜樂的人要同樂；與哀哭的人要同哭。",
   "en": "Rejoice with those who rejoice. Weep with those who weep."
  },
  "16": {
   "zh": "要彼此同心；不要志氣高大，倒要俯就卑微的人（人：或譯事）。不要自以為聰明。",
   "en": "Be of the same mind one toward another. Don’t set your mind on high things, but associate with the humble. Don’t be wise in your own conceits."
  },
  "17": {
   "zh": "不要以惡報惡；眾人以為美的事要留心去做。",
   "en": "Repay no one evil for evil. Respect what is honorable in the sight of all men."
  },
  "18": {
   "zh": "若是能行，總要盡力與眾人和睦。",
   "en": "If it is possible, as much as it is up to you, be at peace with all men."
  },
  "19": {
   "zh": "親愛的弟兄，不要自己伸冤，寧可讓步，聽憑主怒（或譯：讓人發怒）；因為經上記著：「主說：『伸冤在我，我必報應。』」",
   "en": "Don’t seek revenge yourselves, beloved, but give place to God’s wrath. For it is written, “Vengeance belongs to me; I will repay, says the Lord.”"
  },
  "20": {
   "zh": "所以，「你的仇敵若餓了，就給他吃，若渴了，就給他喝；因為你這樣行就是把炭火堆在他的頭上。」",
   "en": "Therefore “If your enemy is hungry, feed him. If he is thirsty, give him a drink; for in doing so, you will heap coals of fire on his head.”"
  },
  "21": {
   "zh": "你不可為惡所勝，反要以善勝惡。",
   "en": "Don’t be overcome by evil, but overcome evil with good."
  }
 },
 "13": {
  "1": {
   "zh": "在上有權柄的，人人當順服他，因為沒有權柄不是出於神的。凡掌權的都是神所命的。",
   "en": "Let every soul be in subjection to the higher authorities, for there is no authority except from God, and those who exist are ordained by God."
  },
  "2": {
   "zh": "所以，抗拒掌權的就是抗拒神的命；抗拒的必自取刑罰。",
   "en": "Therefore he who resists the authority, withstands the ordinance of God; and those who withstand will receive to themselves judgment."
  },
  "3": {
   "zh": "作官的原不是叫行善的懼怕，乃是叫作惡的懼怕。你願意不懼怕掌權的嗎？你只要行善，就可得他的稱讚；",
   "en": "For rulers are not a terror to the good work, but to the evil. Do you desire to have no fear of the authority? Do that which is good, and you will have praise from the same,"
  },
  "4": {
   "zh": "因為他是神的用人，是與你有益的。你若作惡，卻當懼怕；因為他不是空空地佩劍；他是神的用人，是伸冤的，刑罰那作惡的。",
   "en": "for he is a servant of God to you for good. But if you do that which is evil, be afraid, for he doesn’t bear the sword in vain; for he is a servant of God, an avenger for wrath to him who does evil."
  },
  "5": {
   "zh": "所以，你們必須順服，不但是因為刑罰，也是因為良心。",
   "en": "Therefore you need to be in subjection, not only because of the wrath, but also for conscience’ sake."
  },
  "6": {
   "zh": "你們納糧，也為這個緣故；因他們是神的差役，常常特管這事。",
   "en": "For this reason you also pay taxes, for they are servants of God’s service, attending continually on this very thing."
  },
  "7": {
   "zh": "凡人所當得的，就給他。當得糧的，給他納糧；當得稅的，給他上稅；當懼怕的，懼怕他；當恭敬的，恭敬他。",
   "en": "Therefore give everyone what you owe: if you owe taxes, pay taxes; if customs, then customs; if respect, then respect; if honor, then honor."
  },
  "8": {
   "zh": "凡事都不可虧欠人，惟有彼此相愛要常以為虧欠，因為愛人的就完全了律法。",
   "en": "Owe no one anything, except to love one another; for he who loves his neighbor has fulfilled the law."
  },
  "9": {
   "zh": "像那不可姦淫，不可殺人，不可偷盜，不可貪婪，或有別的誡命，都包在愛人如己這一句話之內了。",
   "en": "For the commandments, “You shall not commit adultery,” “You shall not murder,” “You shall not steal,” “You shall not covet,” and whatever other commandments there are, are all summed up in this saying, namely, “You shall love your neighbor as yourself.”"
  },
  "10": {
   "zh": "愛是不加害與人的，所以愛就完全了律法。",
   "en": "Love doesn’t harm a neighbor. Love therefore is the fulfillment of the law."
  },
  "11": {
   "zh": "再者，你們曉得，現今就是該趁早睡醒的時候；因為我們得救，現今比初信的時候更近了。",
   "en": "Do this, knowing the time, that it is already time for you to awaken out of sleep, for salvation is now nearer to us than when we first believed."
  },
  "12": {
   "zh": "黑夜已深，白晝將近。我們就當脫去暗昧的行為，帶上光明的兵器。",
   "en": "The night is far gone, and the day is near. Let’s therefore throw off the deeds of darkness, and let’s put on the armor of light."
  },
  "13": {
   "zh": "行事為人要端正，好像行在白晝。不可荒宴醉酒；不可好色邪蕩；不可爭競嫉妒。",
   "en": "Let us walk properly, as in the day; not in reveling and drunkenness, not in sexual promiscuity and lustful acts, and not in strife and jealousy."
  },
  "14": {
   "zh": "總要披戴主耶穌基督，不要為肉體安排，去放縱私慾。",
   "en": "But put on the Lord Jesus Christ, and make no provision for the flesh, for its lusts."
  }
 },
 "14": {
  "1": {
   "zh": "信心軟弱的，你們要接納，但不要辯論所疑惑的事。",
   "en": "Now accept one who is weak in faith, but not for disputes over opinions."
  },
  "2": {
   "zh": "有人信百物都可吃；但那軟弱的，只吃蔬菜。",
   "en": "One man has faith to eat all things, but he who is weak eats only vegetables."
  },
  "3": {
   "zh": "吃的人不可輕看不吃的人；不吃的人不可論斷吃的人；因為神已經收納他了。",
   "en": "Don’t let him who eats despise him who doesn’t eat. Don’t let him who doesn’t eat judge him who eats, for God has accepted him."
  },
  "4": {
   "zh": "你是誰，竟論斷別人的僕人呢？他或站住或跌倒，自有他的主人在；而且他也必要站住，因為主能使他站住。",
   "en": "Who are you who judge another’s servant? To his own lord he stands or falls. Yes, he will be made to stand, for God has power to make him stand."
  },
  "5": {
   "zh": "有人看這日比那日強；有人看日日都是一樣。只是各人心裡要意見堅定。",
   "en": "One man esteems one day as more important. Another esteems every day alike. Let each man be fully assured in his own mind."
  },
  "6": {
   "zh": "守日的人是為主守的。吃的人是為主吃的，因他感謝神；不吃的人是為主不吃的，也感謝神。",
   "en": "He who observes the day, observes it to the Lord; and he who does not observe the day, to the Lord he does not observe it. He who eats, eats to the Lord, for he gives God thanks. He who doesn’t eat, to the Lord he doesn’t eat, and gives God thanks."
  },
  "7": {
   "zh": "我們沒有一個人為自己活，也沒有一個人為自己死。",
   "en": "For none of us lives to himself, and none dies to himself."
  },
  "8": {
   "zh": "我們若活著，是為主而活；若死了，是為主而死。所以，我們或活或死總是主的人。",
   "en": "For if we live, we live to the Lord. Or if we die, we die to the Lord. If therefore we live or die, we are the Lord’s."
  },
  "9": {
   "zh": "因此，基督死了，又活了，為要作死人並活人的主。",
   "en": "For to this end Christ died, rose, and lived again, that he might be Lord of both the dead and the living."
  },
  "10": {
   "zh": "你這個人，為甚麼論斷弟兄呢？又為甚麼輕看弟兄呢？因我們都要站在神的臺前。",
   "en": "But you, why do you judge your brother? Or you again, why do you despise your brother? For we will all stand before the judgment seat of Christ."
  },
  "11": {
   "zh": "經上寫著：主說：我憑著我的永生起誓：萬膝必向我跪拜；萬口必向我承認。",
   "en": "For it is written, “‘As I live,’ says the Lord, ‘to me every knee will bow. Every tongue will confess to God.’”"
  },
  "12": {
   "zh": "這樣看來，我們各人必要將自己的事在神面前說明。",
   "en": "So then each one of us will give account of himself to God."
  },
  "13": {
   "zh": "所以，我們不可再彼此論斷，寧可定意誰也不給弟兄放下絆腳跌人之物。",
   "en": "Therefore let’s not judge one another any more, but judge this rather, that no man put a stumbling block in his brother’s way, or an occasion for falling."
  },
  "14": {
   "zh": "我憑著主耶穌確知深信，凡物本來沒有不潔淨的；惟獨人以為不潔淨的，在他就不潔淨了。",
   "en": "I know, and am persuaded in the Lord Jesus, that nothing is unclean of itself; except that to him who considers anything to be unclean, to him it is unclean."
  },
  "15": {
   "zh": "你若因食物叫弟兄憂愁，就不是按著愛人的道理行。基督已經替他死，你不可因你的食物叫他敗壞。",
   "en": "Yet if because of food your brother is grieved, you walk no longer in love. Don’t destroy with your food him for whom Christ died."
  },
  "16": {
   "zh": "不可叫你的善被人毀謗；",
   "en": "Then don’t let your good be slandered,"
  },
  "17": {
   "zh": "因為神的國不在乎吃喝，只在乎公義、和平，並聖靈中的喜樂。",
   "en": "for God’s Kingdom is not eating and drinking, but righteousness, peace, and joy in the Holy Spirit."
  },
  "18": {
   "zh": "在這幾樣上服事基督的，就為神所喜悅，又為人所稱許。",
   "en": "For he who serves Christ in these things is acceptable to God and approved by men."
  },
  "19": {
   "zh": "所以，我們務要追求和睦的事與彼此建立德行的事。",
   "en": "So then, let us follow after things which make for peace, and things by which we may build one another up."
  },
  "20": {
   "zh": "不可因食物毀壞神的工程。凡物固然潔淨，但有人因食物叫人跌倒，就是他的罪了。",
   "en": "Don’t overthrow God’s work for food’s sake. All things indeed are clean, however it is evil for that man who creates a stumbling block by eating."
  },
  "21": {
   "zh": "無論是吃肉是喝酒，是甚麼別的事，叫弟兄跌倒，一概不做才好。",
   "en": "It is good to not eat meat, drink wine, nor do anything by which your brother stumbles, is offended, or is made weak."
  },
  "22": {
   "zh": "你有信心，就當在神面前守著。人在自己以為可行的事上能不自責，就有福了。",
   "en": "Do you have faith? Have it to yourself before God. Happy is he who doesn’t judge himself in that which he approves."
  },
  "23": {
   "zh": "若有疑心而吃的，就必有罪，因為他吃不是出於信心。凡不出於信心的都是罪。",
   "en": "But he who doubts is condemned if he eats, because it isn’t of faith; and whatever is not of faith is sin."
  },
  "24": {
   "zh": "",
   "en": "Now to him who is able to establish you according to my Good News and the preaching of Jesus Christ, according to the revelation of the mystery which has been kept secret through long ages,"
  },
  "25": {
   "zh": "",
   "en": "but now is revealed, and by the Scriptures of the prophets, according to the commandment of the eternal God, is made known for obedience of faith to all the nations;"
  },
  "26": {
   "zh": "",
   "en": "to the only wise God, through Jesus Christ, to whom be the glory forever! Amen."
  }
 },
 "15": {
  "1": {
   "zh": "我們堅固的人應該擔代不堅固人的軟弱，不求自己的喜悅。",
   "en": "Now we who are strong ought to bear the weaknesses of the weak, and not to please ourselves."
  },
  "2": {
   "zh": "我們各人務要叫鄰舍喜悅，使他得益處，建立德行。",
   "en": "Let each one of us please his neighbor for that which is good, to be building him up."
  },
  "3": {
   "zh": "因為基督也不求自己的喜悅，如經上所記：「辱罵你人的辱罵都落在我身上。」",
   "en": "For even Christ didn’t please himself. But, as it is written, “The reproaches of those who reproached you fell on me.”"
  },
  "4": {
   "zh": "從前所寫的聖經都是為教訓我們寫的，叫我們因聖經所生的忍耐和安慰可以得著盼望。",
   "en": "For whatever things were written before were written for our learning, that through perseverance and through encouragement of the Scriptures we might have hope."
  },
  "5": {
   "zh": "但願賜忍耐安慰的神叫你們彼此同心，效法基督耶穌，",
   "en": "Now the God of perseverance and of encouragement grant you to be of the same mind one with another according to Christ Jesus,"
  },
  "6": {
   "zh": "一心一口榮耀神─我們主耶穌基督的父！",
   "en": "that with one accord you may with one mouth glorify the God and Father of our Lord Jesus Christ."
  },
  "7": {
   "zh": "所以，你們要彼此接納，如同基督接納你們一樣，使榮耀歸與神。",
   "en": "Therefore accept one another, even as Christ also accepted you, to the glory of God."
  },
  "8": {
   "zh": "我說，基督是為神真理作了受割禮人的執事，要證實所應許列祖的話，",
   "en": "Now I say that Christ has been made a servant of the circumcision for the truth of God, that he might confirm the promises given to the fathers,"
  },
  "9": {
   "zh": "並叫外邦人因他的憐憫榮耀神。如經上所記：因此，我要在外邦中稱讚你，歌頌你的名；",
   "en": "and that the Gentiles might glorify God for his mercy. As it is written, “Therefore will I give praise to you among the Gentiles, and sing to your name.”"
  },
  "10": {
   "zh": "又說：你們外邦人當與主的百姓一同歡樂；",
   "en": "Again he says, “Rejoice, you Gentiles, with his people.”"
  },
  "11": {
   "zh": "又說：外邦啊，你們當讚美主！萬民哪，你們都當頌讚他！",
   "en": "Again, “Praise the Lord, all you Gentiles! Let all the peoples praise him.”"
  },
  "12": {
   "zh": "又有以賽亞說：將來有耶西的根，就是那興起來要治理外邦的；外邦人要仰望他。",
   "en": "Again, Isaiah says, “There will be the root of Jesse, he who arises to rule over the Gentiles; in him the Gentiles will hope.”"
  },
  "13": {
   "zh": "但願使人有盼望的神，因信將諸般的喜樂、平安充滿你們的心，使你們藉著聖靈的能力大有盼望！",
   "en": "Now may the God of hope fill you with all joy and peace in believing, that you may abound in hope, in the power of the Holy Spirit."
  },
  "14": {
   "zh": "弟兄們，我自己也深信你們是滿有良善，充足了諸般的知識，也能彼此勸戒。",
   "en": "I myself am also persuaded about you, my brothers, that you yourselves are full of goodness, filled with all knowledge, able also to admonish others."
  },
  "15": {
   "zh": "但我稍微放膽寫信給你們，是要提醒你們的記性，特因神所給我的恩典，",
   "en": "But I write the more boldly to you in part, as reminding you, because of the grace that was given to me by God,"
  },
  "16": {
   "zh": "使我為外邦人作基督耶穌的僕役，作神福音的祭司，叫所獻上的外邦人，因著聖靈成為聖潔，可蒙悅納。",
   "en": "that I should be a servant of Christ Jesus to the Gentiles, serving as a priest of the Good News of God, that the offering up of the Gentiles might be made acceptable, sanctified by the Holy Spirit."
  },
  "17": {
   "zh": "所以論到神的事，我在基督耶穌裡有可誇的。",
   "en": "I have therefore my boasting in Christ Jesus in things pertaining to God."
  },
  "18": {
   "zh": "除了基督藉我做的那些事，我甚麼都不敢提，只提他藉我言語作為，用神蹟奇事的能力，並聖靈的能力，使外邦人順服；",
   "en": "For I will not dare to speak of any things except those which Christ worked through me, for the obedience of the Gentiles, by word and deed,"
  },
  "19": {
   "zh": "甚至我從耶路撒冷，直轉到以利哩古，到處傳了基督的福音。",
   "en": "in the power of signs and wonders, in the power of God’s Spirit; so that from Jerusalem, and around as far as to Illyricum, I have fully preached the Good News of Christ;"
  },
  "20": {
   "zh": "我立了志向，不在基督的名被稱過的地方傳福音，免得建造在別人的根基上。",
   "en": "yes, making it my aim to preach the Good News, not where Christ was already named, that I might not build on another’s foundation."
  },
  "21": {
   "zh": "就如經上所記：未曾聞知他信息的，將要看見；未曾聽過的，將要明白。",
   "en": "But, as it is written, “They will see, to whom no news of him came. They who haven’t heard will understand.”"
  },
  "22": {
   "zh": "我因多次被攔阻，總不得到你們那裡去。",
   "en": "Therefore also I was hindered these many times from coming to you,"
  },
  "23": {
   "zh": "但如今，在這裡再沒有可傳的地方，而且這好幾年，我切心想望到西班牙去的時候，可以到你們那裡，",
   "en": "but now, no longer having any place in these regions, and having these many years a longing to come to you,"
  },
  "24": {
   "zh": "盼望從你們那裡經過，得見你們，先與你們彼此交往，心裡稍微滿足，然後蒙你們送行。",
   "en": "whenever I travel to Spain, I will come to you. For I hope to see you on my journey, and to be helped on my way there by you, if first I may enjoy your company for a while."
  },
  "25": {
   "zh": "但現在，我往耶路撒冷去供給聖徒。",
   "en": "But now, I say, I am going to Jerusalem, serving the saints."
  },
  "26": {
   "zh": "因為馬其頓和亞該亞人樂意湊出捐項給耶路撒冷聖徒中的窮人。",
   "en": "For it has been the good pleasure of Macedonia and Achaia to make a certain contribution for the poor among the saints who are at Jerusalem."
  },
  "27": {
   "zh": "這固然是他們樂意的，其實也算是所欠的債；因外邦人既然在他們屬靈的好處上有分，就當把養身之物供給他們。",
   "en": "Yes, it has been their good pleasure, and they are their debtors. For if the Gentiles have been made partakers of their spiritual things, they owe it to them also to serve them in fleshly things."
  },
  "28": {
   "zh": "等我辦完了這事，把這善果向他們交付明白，我就要路過你們那裡，往西班牙去。",
   "en": "When therefore I have accomplished this, and have sealed to them this fruit, I will go on by way of you to Spain."
  },
  "29": {
   "zh": "我也曉得，去的時候必帶著基督豐盛的恩典而去。",
   "en": "I know that, when I come to you, I will come in the fullness of the blessing of the Good News of Christ."
  },
  "30": {
   "zh": "弟兄們，我藉著我們主耶穌基督，又藉著聖靈的愛，勸你們與我一同竭力，為我祈求神，",
   "en": "Now I beg you, brothers, by our Lord Jesus Christ, and by the love of the Spirit, that you strive together with me in your prayers to God for me,"
  },
  "31": {
   "zh": "叫我脫離在猶太不順從的人，也叫我為耶路撒冷所辦的捐項可蒙聖徒悅納，",
   "en": "that I may be delivered from those who are disobedient in Judea, and that my service which I have for Jerusalem may be acceptable to the saints;"
  },
  "32": {
   "zh": "並叫我順著神的旨意，歡歡喜喜地到你們那裡，與你們同得安息。",
   "en": "that I may come to you in joy through the will of God, and together with you, find rest."
  },
  "33": {
   "zh": "願賜平安的神常和你們眾人同在。阿們！",
   "en": "Now the God of peace be with you all. Amen."
  }
 },
 "16": {
  "1": {
   "zh": "我對你們舉薦我們的姊妹非比；她是堅革哩教會中的女執事。",
   "en": "I commend to you Phoebe, our sister, who is a servant of the assembly that is at Cenchreae,"
  },
  "2": {
   "zh": "請你們為主接待她，合乎聖徒的體統。她在何事上要你們幫助，你們就幫助她；因她素來幫助許多人，也幫助了我。",
   "en": "that you receive her in the Lord, in a way worthy of the saints, and that you assist her in whatever matter she may need from you, for she herself also has been a helper of many, and of my own self."
  },
  "3": {
   "zh": "問百基拉和亞居拉安。他們在基督耶穌裡與我同工，",
   "en": "Greet Prisca and Aquila, my fellow workers in Christ Jesus,"
  },
  "4": {
   "zh": "也為我的命將自己的頸項置之度外。不但我感謝他們，就是外邦的眾教會也感謝他們。",
   "en": "who for my life, laid down their own necks; to whom not only I give thanks, but also all the assemblies of the Gentiles."
  },
  "5": {
   "zh": "又問在他們家中的教會安。問我所親愛的以拜尼土安；他在亞細亞是歸基督初結的果子。",
   "en": "Greet the assembly that is in their house. Greet Epaenetus, my beloved, who is the first fruits of Achaia to Christ."
  },
  "6": {
   "zh": "又問馬利亞安；她為你們多受勞苦。",
   "en": "Greet Mary, who labored much for us."
  },
  "7": {
   "zh": "又問我親屬與我一同坐監的安多尼古和猶尼亞安；他們在使徒中是有名望的，也是比我先在基督裡。",
   "en": "Greet Andronicus and Junia, my relatives and my fellow prisoners, who are notable among the apostles, who were also in Christ before me."
  },
  "8": {
   "zh": "又問我在主裡面所親愛的暗伯利安。",
   "en": "Greet Amplias, my beloved in the Lord."
  },
  "9": {
   "zh": "又問在基督裡與我們同工的耳巴奴，並我所親愛的士大古安。",
   "en": "Greet Urbanus, our fellow worker in Christ, and Stachys, my beloved."
  },
  "10": {
   "zh": "又問在基督裡經過試驗的亞比利安。問亞利多布家裡的人安。",
   "en": "Greet Apelles, the approved in Christ. Greet those who are of the household of Aristobulus."
  },
  "11": {
   "zh": "又問我親屬希羅天安。問拿其數家在主裡的人安。",
   "en": "Greet Herodion, my kinsman. Greet them of the household of Narcissus, who are in the Lord."
  },
  "12": {
   "zh": "又問為主勞苦的土非拿氏和土富撒氏安。問可親愛為主多受勞苦的彼息氏安。",
   "en": "Greet Tryphaena and Tryphosa, who labor in the Lord. Greet Persis, the beloved, who labored much in the Lord."
  },
  "13": {
   "zh": "又問在主蒙揀選的魯孚和他母親安；他的母親就是我的母親。",
   "en": "Greet Rufus, the chosen in the Lord, and his mother and mine."
  },
  "14": {
   "zh": "又問亞遜其土、弗勒干、黑米、八羅巴、黑馬，並與他們在一處的弟兄們安。",
   "en": "Greet Asyncritus, Phlegon, Hermes, Patrobas, Hermas, and the brothers who are with them."
  },
  "15": {
   "zh": "又問非羅羅古和猶利亞，尼利亞和他姊妹，同阿林巴並與他們在一處的眾聖徒安。",
   "en": "Greet Philologus and Julia, Nereus and his sister, and Olympas, and all the saints who are with them."
  },
  "16": {
   "zh": "你們親嘴問安，彼此務要聖潔。基督的眾教會都問你們安。",
   "en": "Greet one another with a holy kiss. The assemblies of Christ greet you."
  },
  "17": {
   "zh": "弟兄們，那些離間你們、叫你們跌倒、背乎所學之道的人，我勸你們要留意躲避他們。",
   "en": "Now I beg you, brothers, look out for those who are causing the divisions and occasions of stumbling, contrary to the doctrine which you learned, and turn away from them."
  },
  "18": {
   "zh": "因為這樣的人不服事我們的主基督，只服事自己的肚腹，用花言巧語誘惑那些老實人的心。",
   "en": "For those who are such don’t serve our Lord, Jesus Christ, but their own belly; and by their smooth and flattering speech, they deceive the hearts of the innocent."
  },
  "19": {
   "zh": "你們的順服已經傳於眾人，所以我為你們歡喜；但我願意你們在善上聰明，在惡上愚拙。",
   "en": "For your obedience has become known to all. I rejoice therefore over you. But I desire to have you wise in that which is good, but innocent in that which is evil."
  },
  "20": {
   "zh": "賜平安的神快要將撒但踐踏在你們腳下。願我主耶穌基督的恩常和你們同在！",
   "en": "And the God of peace will quickly crush Satan under your feet. The grace of our Lord Jesus Christ be with you."
  },
  "21": {
   "zh": "與我同工的提摩太，和我的親屬路求、耶孫、所西巴德，問你們安。",
   "en": "Timothy, my fellow worker, greets you, as do Lucius, Jason, and Sosipater, my relatives."
  },
  "22": {
   "zh": "我這代筆寫信的德丟，在主裡面問你們安。",
   "en": "I, Tertius, who write the letter, greet you in the Lord."
  },
  "23": {
   "zh": "那接待我、也接待全教會的該猶問你們安。",
   "en": "Gaius, my host and host of the whole assembly, greets you. Erastus, the treasurer of the city, greets you, as does Quartus, the brother."
  },
  "24": {
   "zh": "城內管銀庫的以拉都和兄弟括土問你們安。",
   "en": "The grace of our Lord Jesus Christ be with you all! Amen."
  },
  "25": {
   "zh": "惟有神能照我所傳的福音和所講的耶穌基督，並照永古隱藏不言的奧祕，堅固你們的心。",
   "en": ""
  },
  "26": {
   "zh": "這奧祕如今顯明出來，而且按著永生神的命，藉眾先知的書指示萬國的民，使他們信服真道。",
   "en": ""
  },
  "27": {
   "zh": "願榮耀，因耶穌基督，歸與獨一全智的神，直到永遠。阿們！",
   "en": ""
  }
 }
};
